<script>
(function() {
  const container = document.getElementById('containerSecciones3D');
  const wrapper = document.getElementById('wrapperSecciones3D');
  const canvas = document.getElementById('canvasSecciones3D');
  const ctx = canvas.getContext('2d');
  const sliderN = document.getElementById('sliderN_sec');
  const valN = document.getElementById('valN_sec');
  const infoOverlay = document.getElementById('infoSecciones3D');
  const btnAnim = document.getElementById('btnAnim_sec');

  const btnSquare = document.getElementById('btnShapeSquare');
  const btnSemi = document.getElementById('btnShapeSemi');
  const btnTri = document.getElementById('btnShapeTri');

  // Etiquetas KaTeX flotantes
  const lblBase = document.getElementById('labelBase_sec');
  const lblSlice = document.getElementById('labelSlice_sec');

  // Estado del modelo
  let shapeType = 'square'; // 'square', 'semi', 'tri'
  let numN = parseInt(sliderN.value);
  let sweepIndex = numN; // Cuántas rodajas mostrar (para el barrido animado)
  let isAnimating = false;
  let animId = null;

  // Cámara (Estándar 1 Oficial)
  let yaw = -0.65;
  let pitch = 0.45;
  let zoom = 1.0;
  let panX = 0;
  let panY = 0;

  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };

  // Proyección 3D a 2D
  function project3D(x, y, z) {
    const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
    const x1 = x * cosY - y * sinY;
    const y1 = x * sinY + y * cosY;
    const z1 = z;

    const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
    const x2 = x1;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;

    const currentScale = 35 * zoom;
    const cx = canvas.width / 2 + panX;
    const cy = canvas.height / 2 + panY;

    return {
      px: cx + x2 * currentScale,
      py: cy - z2 * currentScale,
      zDepth: y2
    };
  }

  function drawLine3D(pA, pB, color, width = 1.5, dash = []) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    ctx.save();
    ctx.beginPath();
    ctx.setLineDash(dash);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();
    ctx.restore();
  }

  function drawVector3D(pA, pB, color, width = 2) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    const dx = b.px - a.px;
    const dy = b.py - a.py;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) return;

    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();

    const angle = Math.atan2(dy, dx);
    const headLen = 9;
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.moveTo(b.px, b.py);
    ctx.lineTo(b.px - headLen * Math.cos(angle - Math.PI / 6), b.py - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(b.px - headLen * Math.cos(angle + Math.PI / 6), b.py - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawGrid3D() {
    ctx.beginPath();
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = -1; i <= 5; i++) {
      const pA1 = project3D(i, -1, 0), pA2 = project3D(i, 5, 0);
      ctx.moveTo(pA1.px, pA1.py); ctx.lineTo(pA2.px, pA2.py);

      const pB1 = project3D(-1, i, 0), pB2 = project3D(5, i, 0);
      ctx.moveTo(pB1.px, pB1.py); ctx.lineTo(pB2.px, pB2.py);
    }
    ctx.stroke();
  }

  function drawAxes3D() {
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, { x: 5.2, y: 0, z: 0 }, '#000000', 2.0); // Eje X
    drawVector3D(O, { x: 0, y: 5.2, z: 0 }, '#000000', 2.0); // Eje Y
    drawVector3D(O, { x: 0, y: 0, z: 5.2 }, '#000000', 2.0); // Eje Z

    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#000000';
    const px = project3D(5.5, 0, 0);
    const py = project3D(0, 5.5, 0);
    const pz = project3D(0, 0, 5.5);

    ctx.fillText('x', px.px, px.py);
    ctx.fillText('y', py.px, py.py);
    ctx.fillText('z', pz.px, pz.py);

    // Graduación Eje Z
    for (let zVal = 1; zVal <= 5; zVal++) {
      const ptZ = project3D(0, 0, zVal);
      const ptTick = project3D(0.12, 0, zVal);

      ctx.save();
      ctx.beginPath();
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 1.2;
      ctx.moveTo(ptZ.px, ptZ.py);
      ctx.lineTo(ptTick.px, ptTick.py);
      ctx.stroke();

      ctx.font = '10px sans-serif';
      ctx.fillStyle = '#334155';
      ctx.fillText(zVal.toString(), ptTick.px + 4, ptTick.py + 3);
      ctx.restore();
    }
  }

  // Dibujar la base del plano xy: y = +- sqrt(x) para x en [0, 4]
  function drawBaseRegion() {
    const steps = 40;
    ctx.save();
    ctx.beginPath();

    // Parábola superior y = +sqrt(x)
    for (let i = 0; i <= steps; i++) {
      const x = (i / steps) * 4.0;
      const y = Math.sqrt(x);
      const p2D = project3D(x, y, 0);
      if (i === 0) ctx.moveTo(p2D.px, p2D.py);
      else ctx.lineTo(p2D.px, p2D.py);
    }
    // Parábola inferior y = -sqrt(x)
    for (let i = steps; i >= 0; i--) {
      const x = (i / steps) * 4.0;
      const y = -Math.sqrt(x);
      const p2D = project3D(x, y, 0);
      ctx.lineTo(p2D.px, p2D.py);
    }
    ctx.closePath();

    ctx.fillStyle = 'rgba(2, 132, 199, 0.12)';
    ctx.fill();
    ctx.strokeStyle = '#0284c7';
    ctx.lineWidth = 2.0;
    ctx.stroke();
    ctx.restore();
  }

  // Generar perfil 3D en x de una sección transversal
  function getSliceProfile(x) {
    const yHalf = Math.sqrt(x); // Ancho total en y es 2*yHalf
    const width = 2 * yHalf;
    const pts = [];

    if (shapeType === 'square') {
      // Cuadrado de lado = width en Z
      pts.push({ y: -yHalf, z: 0 });
      pts.push({ y: yHalf, z: 0 });
      pts.push({ y: yHalf, z: width });
      pts.push({ y: -yHalf, z: width });
    } else if (shapeType === 'semi') {
      // Semicírculo de diámetro = width en Z
      const numPts = 12;
      for (let i = 0; i <= numPts; i++) {
        const ang = (i / numPts) * Math.PI;
        pts.push({
          y: yHalf * Math.cos(ang),
          z: yHalf * Math.sin(ang)
        });
      }
    } else if (shapeType === 'tri') {
      // Triángulo equilátero de lado = width
      const h = (Math.sqrt(3) / 2) * width;
      pts.push({ y: -yHalf, z: 0 });
      pts.push({ y: yHalf, z: 0 });
      pts.push({ y: 0, z: h });
    }
    return pts;
  }

  // Dibujar las N rodajas 3D extruidas
  function drawSlices() {
    const dx = 4.0 / numN;
    const maxK = Math.min(numN, sweepIndex);

    for (let k = 0; k < maxK; k++) {
      const xA = k * dx;
      const xB = (k + 1) * dx;

      const profileA = getSliceProfile(xA);
      const profileB = getSliceProfile(xB);

      const ptsA2D = profileA.map(p => project3D(xA, p.y, p.z));
      const ptsB2D = profileB.map(p => project3D(xB, p.y, p.z));

      // Color especial si es la rodaja destacada (la última del barrido)
      const isHighlighted = (k === maxK - 1 && isAnimating);

      ctx.save();

      // Cara frontal A
      ctx.beginPath();
      ptsA2D.forEach((pt, idx) => {
        if (idx === 0) ctx.moveTo(pt.px, pt.py);
        else ctx.lineTo(pt.px, pt.py);
      });
      ctx.closePath();
      ctx.fillStyle = isHighlighted ? 'rgba(225, 29, 72, 0.4)' : 'rgba(56, 189, 248, 0.25)';
      ctx.fill();
      ctx.strokeStyle = isHighlighted ? '#e11d48' : 'rgba(2, 132, 199, 0.6)';
      ctx.lineWidth = 1.0;
      ctx.stroke();

      // Caras laterales extruidas de A a B
      const numP = profileA.length;
      for (let i = 0; i < numP; i++) {
        const iNext = (i + 1) % numP;
        ctx.beginPath();
        ctx.moveTo(ptsA2D[i].px, ptsA2D[i].py);
        ctx.lineTo(ptsA2D[iNext].px, ptsA2D[iNext].py);
        ctx.lineTo(ptsB2D[iNext].px, ptsB2D[iNext].py);
        ctx.lineTo(ptsB2D[i].px, ptsB2D[i].py);
        ctx.closePath();
        ctx.fillStyle = isHighlighted ? 'rgba(225, 29, 72, 0.3)' : 'rgba(56, 189, 248, 0.18)';
        ctx.fill();
        ctx.stroke();
      }

      ctx.restore();
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawGrid3D();
    drawAxes3D();
    drawBaseRegion();
    drawSlices();

    // Posición de etiquetas KaTeX flotantes
    const posBase  = project3D(2.0, -1.8, 0);
    const posSlice = project3D(3.0, 0, Math.sqrt(3.0) * 1.2);

    if (lblBase)  { lblBase.style.left  = posBase.px + 'px';  lblBase.style.top  = (posBase.py - 10) + 'px'; }
    if (lblSlice) { lblSlice.style.left = posSlice.px + 'px'; lblSlice.style.top = (posSlice.py - 12) + 'px'; }

    // Actualizar Panel Overlay KaTeX
    if (infoOverlay) {
      let areaFormula = '', volExact = '';
      if (shapeType === 'square') {
        areaFormula = '\\(A(x) = 4x\\)';
        volExact = '\\(V = \\int_0^4 4x \\, dx = 32\\)';
      } else if (shapeType === 'semi') {
        areaFormula = '\\(A(x) = \\frac{\\pi}{2} x\\)';
        volExact = '\\(V = \\frac{\\pi}{2} \\int_0^4 x \\, dx = 4\\pi \\approx 12.57\\)';
      } else if (shapeType === 'tri') {
        areaFormula = '\\(A(x) = \\sqrt{3} x\\)';
        volExact = '\\(V = \\sqrt{3} \\int_0^4 x \\, dx = 8\\sqrt{3} \\approx 13.86\\)';
      }

      infoOverlay.innerHTML = `
        <div style="color: #0284c7; font-weight: 700; margin-bottom: 3px;">Secciones Transversales Conocidas</div>
        <div style="color: #334155; font-size: 12px;">Base: \\(y = \\pm\\sqrt{x}\\), \\(x \\in [0, 4]\\)</div>
        <div style="color: #059669; font-size: 12px; margin-top: 2px;">Área de la Sección: ${areaFormula}</div>
        <div style="color: #e11d48; font-weight: 700; font-size: 12px; margin-top: 3px;">Volumen Exacto: ${volExact}</div>
        <div style="color: #64748b; font-size: 11px; margin-top: 2px;">Rodajas de Riemann: \\(N = ${numN}\\) (\\(\\Delta x = ${(4.0/numN).toFixed(2)}\\))</div>
      `;

      if (window.renderMathInElement) {
        window.renderMathInElement(infoOverlay, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }

  // Eventos de botones de forma
  btnSquare.onclick = () => {
    shapeType = 'square';
    btnSquare.style.background = '#0284c7'; btnSquare.style.color = '#ffffff';
    btnSemi.style.background = '#f1f5f9'; btnSemi.style.color = '#334155';
    btnTri.style.background = '#f1f5f9'; btnTri.style.color = '#334155';
    draw();
  };

  btnSemi.onclick = () => {
    shapeType = 'semi';
    btnSquare.style.background = '#f1f5f9'; btnSquare.style.color = '#334155';
    btnSemi.style.background = '#0284c7'; btnSemi.style.color = '#ffffff';
    btnTri.style.background = '#f1f5f9'; btnTri.style.color = '#334155';
    draw();
  };

  btnTri.onclick = () => {
    shapeType = 'tri';
    btnSquare.style.background = '#f1f5f9'; btnSquare.style.color = '#334155';
    btnSemi.style.background = '#f1f5f9'; btnSemi.style.color = '#334155';
    btnTri.style.background = '#0284c7'; btnTri.style.color = '#ffffff';
    draw();
  };

  // Slider N
  sliderN.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    numN = parseInt(e.target.value);
    valN.textContent = numN;
    sweepIndex = numN;
    draw();
  });

  // Animación de barrido
  function animateSweep() {
    if (isAnimating) {
      stopAnimation();
      return;
    }

    isAnimating = true;
    btnAnim.innerHTML = '⏸ Pausar';
    sweepIndex = 1;

    function stepAnim() {
      if (!isAnimating) return;
      draw();
      sweepIndex++;
      if (sweepIndex > numN) {
        stopAnimation();
        sweepIndex = numN;
        draw();
        return;
      }
      setTimeout(() => { animId = requestAnimationFrame(stepAnim); }, 120);
    }

    stepAnim();
  }

  function stopAnimation() {
    isAnimating = false;
    if (animId) cancelAnimationFrame(animId);
    btnAnim.innerHTML = '▶ Barrido 3D';
  }

  btnAnim.onclick = animateSweep;

  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - prevMousePos.x;
    const deltaY = e.clientY - prevMousePos.y;

    yaw += deltaX * 0.008;
    pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));

    prevMousePos = { x: e.clientX, y: e.clientY };
    draw();
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });

  // Zoom con Rueda
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const oldZoom = zoom;
    let newZoom = oldZoom;

    if (e.deltaY < 0) newZoom = Math.min(3.5, oldZoom * 1.08);
    else newZoom = Math.max(0.3, oldZoom / 1.08);

    if (e.shiftKey) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const scaleRatio = newZoom / oldZoom;
      const originX = (canvas.width / 2) + panX;
      const originY = (canvas.height / 2) + panY;

      panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
      panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2);
    }

    zoom = newZoom;
    draw();
  }, { passive: false });

  // Traslación con Flechas
  window.addEventListener('keydown', (e) => {
    if (document.activeElement === sliderN) return;
    const step = 15;
    if (e.key === 'ArrowLeft') { panX -= step; draw(); }
    else if (e.key === 'ArrowRight') { panX += step; draw(); }
    else if (e.key === 'ArrowUp') { panY -= step; draw(); }
    else if (e.key === 'ArrowDown') { panY += step; draw(); }
  });

  // Botones de Vistas Ortogonales
  document.getElementById('btnVX_sec').onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
  document.getElementById('btnVY_sec').onclick = () => { yaw = 0; pitch = 0; draw(); };
  document.getElementById('btnVZ_sec').onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };
  document.getElementById('btnReset_sec').onclick = () => {
    yaw = -0.65; pitch = 0.45; zoom = 1.0; panX = 0; panY = 0; draw();
  };

  // Pantalla Completa Adaptativa 100%
  document.getElementById('btnFS_sec').onclick = () => {
    if (!document.fullscreenElement) {
      if (container.requestFullscreen) container.requestFullscreen();
      else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
    } else {
      if (document.exitFullscreen) document.exitFullscreen();
    }
  };

  function updateCanvasSize() {
    if (document.fullscreenElement) {
      container.style.width = '100vw';
      container.style.height = '100vh';
      container.style.borderRadius = '0';
      container.style.padding = '16px';
      container.style.display = 'flex';
      container.style.flexDirection = 'column';
      container.style.justifyContent = 'space-between';

      const controlsHeight = 130;
      wrapper.style.width = '100%';
      wrapper.style.height = `${window.innerHeight - controlsHeight}px`;

      canvas.width = wrapper.clientWidth;
      canvas.height = window.innerHeight - controlsHeight;
    } else {
      container.style.width = '';
      container.style.height = '';
      container.style.borderRadius = '16px';
      container.style.padding = '16px';
      container.style.display = 'inline-block';

      wrapper.style.width = '620px';
      wrapper.style.height = '400px';

      canvas.width = 620;
      canvas.height = 400;
    }
    draw();
  }

  document.addEventListener('fullscreenchange', updateCanvasSize);
  window.addEventListener('resize', updateCanvasSize);

  draw();
})();
</script>
\end{html}

\begin{card}
\begin{definicion}{Volumen Sólido de Revolución: Método de los Discos y Arandelas al rededor del eje $x$.}
Sea una región plana acotada por las curvas continuas $y = R(x)$ (radio externo) y $y = r(x)$ (radio interno), con $0 \le r(x) \le R(x)$ en el intervalo $x \in [a, b]$.
Al girar esta región alrededor del eje $x$, se genera un sólido de revolución cuyo volumen $V$ viene dado por la suma de Riemann de arandelas circulares de grosor $\Delta x$:
$$V = \lim_{N \to \infty} \sum_{i=1}^N \pi \left( [R(x_i^*)]^2 - [r(x_i^*)]^2 \right) \Delta x = \pi \int_a^b \left( [R(x)]^2 - [r(x)]^2 \right) dx$$
En el caso particular en que el radio interno sea nulo ($r(x) = 0$), las arandelas se convierten en \textbf{discos sólidos} y la fórmula se reduce a:
$$V = \pi \int_a^b [R(x)]^2 dx$$
\end{definicion}

