<script>
(function() {
  const container = document.getElementById('containerArandelasYc3D');
  const wrapper = document.getElementById('wrapperArandelasYc3D');
  const canvas = document.getElementById('canvasArandelasYc3D');
  const ctx = canvas.getContext('2d');

  const sliderN = document.getElementById('sliderN_arandelaYc');
  const valN = document.getElementById('valN_arandelaYc');
  const sliderTheta = document.getElementById('sliderTheta_arandelaYc');
  const valTheta = document.getElementById('valTheta_arandelaYc');
  const sliderC = document.getElementById('sliderAxisC');
  const valC = document.getElementById('valAxisC');

  const infoOverlay = document.getElementById('infoArandelasYc3D');
  const btnAnim = document.getElementById('btnAnim_arandelaYc');

  const btnArandela = document.getElementById('btnModeArandelaYc');
  const btnDisco = document.getElementById('btnModeDiscoYc');

  // Etiquetas KaTeX flotantes
  const lblBase = document.getElementById('labelBase_arandelaYc');
  const lblLower = document.getElementById('labelLower_arandelaYc');

  // Modo: 'arandela' o 'disco'
  let mode = 'arandela';

  // Dominio en X: x in [0, 4]
  const a = 0.0;
  const b = 4.0;
  let axisC = parseFloat(sliderC.value);

  // Funciones base: f(x) = sqrt(x), g(x) = x/2
  const f_curve = (x) => Math.sqrt(Math.max(0, x));
  const g_curve = (x) => x / 2.0;

  // Lógica de 2 Fases para los radios según la posición del eje c:
  // Si c > 2 (por encima): R(x) = |g(x) - c|, r(x) = |f(x) - c|
  // Si c < 0 (por debajo): R(x) = |f(x) - c|, r(x) = |g(x) - c|
  function R_ext(x) {
    if (axisC > 2.0) {
      return Math.abs(g_curve(x) - axisC);
    } else {
      return Math.abs(f_curve(x) - axisC);
    }
  }

  function r_int(x) {
    if (mode === 'disco') return 0.0;
    if (axisC > 2.0) {
      return Math.abs(f_curve(x) - axisC);
    } else {
      return Math.abs(g_curve(x) - axisC);
    }
  }

  // Integración numérica Simpson para exactitud en cualquier c y modo
  function getVExact() {
    const nSteps = 100;
    const h = (b - a) / nSteps;
    let sum = 0.0;
    for (let i = 0; i <= nSteps; i++) {
      const xVal = a + i * h;
      const R_val = R_ext(xVal);
      const r_val = r_int(xVal);
      const area = Math.PI * (R_val * R_val - r_val * r_val);
      const weight = (i === 0 || i === nSteps) ? 1.0 : (i % 2 === 1 ? 4.0 : 2.0);
      sum += weight * area;
    }
    return (h / 3.0) * sum;
  }

  let numN = parseInt(sliderN.value);
  let thetaDeg = parseFloat(sliderTheta.value);
  let sweepIndex = numN;
  let isAnimating = false;
  let animId = null;

  // Cámara (Estándar 1 y 2 Oficial)
  let yaw = -0.65;
  let pitch = 0.45;
  let zoom = 1.0;
  let panX = 0;
  let panY = 0;

  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };

  // Proyección 3D a 2D (Software Engine Canvas 2D)
  function project3D(x, y, z) {
    const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
    const x1 = x * cosY - y * sinY;
    const y1 = x * sinY + y * cosY;
    const z1 = z;

    const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
    const x2 = x1;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;

    const currentScale = 32 * zoom;
    const cx = canvas.width / 2 + panX;
    const cy = canvas.height / 2 + panY + 20;

    return {
      px: cx + x2 * currentScale,
      py: cy - z2 * currentScale,
      zDepth: y2
    };
  }

  function drawVector3D(pA, pB, color, width = 2) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    const dx = b.px - a.px;
    const dy = b.py - a.py;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) return;

    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();

    const angle = Math.atan2(dy, dx);
    const headLen = 9;
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.moveTo(b.px, b.py);
    ctx.lineTo(b.px - headLen * Math.cos(angle - Math.PI / 6), b.py - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(b.px - headLen * Math.cos(angle + Math.PI / 6), b.py - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // REJILLA/CUADRICULADO EN Z=0
  function drawGrid3D() {
    ctx.beginPath();
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1.0;
    const minVal = -4;
    const maxVal = 5;

    // 1. Líneas paralelas al Eje Y (x constante)
    for (let x = minVal; x <= maxVal; x++) {
      const pA = project3D(x, minVal, 0);
      const pB = project3D(x, maxVal, 0);
      ctx.moveTo(pA.px, pA.py);
      ctx.lineTo(pB.px, pB.py);
    }

    // 2. Líneas paralelas al Eje X (y constante)
    for (let y = minVal; y <= maxVal; y++) {
      const pA = project3D(minVal, y, 0);
      const pB = project3D(maxVal, y, 0);
      ctx.moveTo(pA.px, pA.py);
      ctx.lineTo(pB.px, pB.py);
    }
    ctx.stroke();
  }

  function drawAxes3D() {
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, { x: 5.0, y: 0, z: 0 }, '#000000', 2.0); // Eje X
    drawVector3D(O, { x: 0, y: 4.5, z: 0 }, '#000000', 2.0); // Eje Y
    drawVector3D(O, { x: 0, y: 0, z: 4.0 }, '#000000', 2.0); // Eje Z (sin graduación)

    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#000000';
    const px = project3D(5.3, 0, 0);
    const py = project3D(0, 4.8, 0);
    const pz = project3D(0, 0, 4.3);

    ctx.fillText('x', px.px, px.py);
    ctx.fillText('y', py.px, py.py);
    ctx.fillText('z', pz.px, pz.py);

    // Eje de Rotación y = c (Línea naranja destacada en 3D)
    const pA_axis = project3D(-0.5, axisC, 0);
    const pB_axis = project3D(5.0, axisC, 0);
    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = '#d97706';
    ctx.lineWidth = 2.0;
    ctx.setLineDash([5, 4]);
    ctx.moveTo(pA_axis.px, pA_axis.py);
    ctx.lineTo(pB_axis.px, pB_axis.py);
    ctx.stroke();

    ctx.font = 'bold 11px sans-serif';
    ctx.fillStyle = '#d97706';
    ctx.fillText(`Eje y = ${axisC.toFixed(1)}`, pB_axis.px + 4, pB_axis.py + 3);
    ctx.restore();
  }

  // Dibujar curvas generatrices f(x) y g(x) y región 2D base sobre el plano XY (z=0)
  function drawBaseRegionXY() {
    const steps = 40;
    ctx.save();

    // Sombreado de la región plana entre f(x) y g(x)
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const xVal = a + (i / steps) * (b - a);
      const yVal = f_curve(xVal);
      const pt = project3D(xVal, yVal, 0);
      if (i === 0) ctx.moveTo(pt.px, pt.py);
      else ctx.lineTo(pt.px, pt.py);
    }
    for (let i = steps; i >= 0; i--) {
      const xVal = a + (i / steps) * (b - a);
      const yVal = g_curve(xVal);
      const pt = project3D(xVal, yVal, 0);
      ctx.lineTo(pt.px, pt.py);
    }
    ctx.closePath();
    ctx.fillStyle = 'rgba(2, 132, 199, 0.15)';
    ctx.fill();

    // Trazo de f(x) = sqrt(x) (Azul)
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const xVal = a + (i / steps) * (b - a);
      const pt = project3D(xVal, f_curve(xVal), 0);
      if (i === 0) ctx.moveTo(pt.px, pt.py);
      else ctx.lineTo(pt.px, pt.py);
    }
    ctx.strokeStyle = '#0284c7';
    ctx.lineWidth = 2.0;
    ctx.stroke();

    // Trazo de g(x) = x/2 (Verde)
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const xVal = a + (i / steps) * (b - a);
      const pt = project3D(xVal, g_curve(xVal), 0);
      if (i === 0) ctx.moveTo(pt.px, pt.py);
      else ctx.lineTo(pt.px, pt.py);
    }
    ctx.strokeStyle = '#059669';
    ctx.lineWidth = 2.0;
    ctx.stroke();

    ctx.restore();
  }

  // Dibujar Arandelas / Discos en 3D alrededor de la recta y = c (Painter's Algorithm)
  function drawWashersYc3D() {
    const maxTheta = (thetaDeg * Math.PI) / 180.0;
    const dx = (b - a) / numN;
    const maxK = Math.min(numN, sweepIndex);

    const faces = [];
    const numAng = Math.max(16, Math.floor(24 * (maxTheta / (2 * Math.PI))));

    for (let k = 0; k < maxK; k++) {
      const x1 = a + k * dx;
      const x2 = a + (k + 1) * dx;
      const xMid = (x1 + x2) / 2.0;

      const R_val = R_ext(xMid);
      const r_val = r_int(xMid);

      if (R_val <= 0.001) continue;

      const isHighlighted = (k === maxK - 1 && isAnimating);

      for (let j = 0; j < numAng; j++) {
        const thA = (j / numAng) * maxTheta;
        const thB = ((j + 1) / numAng) * maxTheta;

        const cosA = Math.cos(thA), sinA = Math.sin(thA);
        const cosB = Math.cos(thB), sinB = Math.sin(thB);

        // Al girar alrededor de y = c:
        // x es la posición en X, y = c + Radius*cos(theta), z = Radius*sin(theta)
        const pOutBotA = { x: x1, y: axisC + R_val * cosA, z: R_val * sinA };
        const pOutBotB = { x: x1, y: axisC + R_val * cosB, z: R_val * sinB };
        const pOutTopB = { x: x2, y: axisC + R_val * cosB, z: R_val * sinB };
        const pOutTopA = { x: x2, y: axisC + R_val * cosA, z: R_val * sinA };

        const pInBotA = { x: x1, y: axisC + r_val * cosA, z: r_val * sinA };
        const pInBotB = { x: x1, y: axisC + r_val * cosB, z: r_val * sinB };
        const pInTopB = { x: x2, y: axisC + r_val * cosB, z: r_val * sinB };
        const pInTopA = { x: x2, y: axisC + r_val * cosA, z: r_val * sinA };

        const hue = 0.95 - (k / numN) * 0.15;
        const fillCol = isHighlighted ? 'rgba(225, 29, 72, 0.55)' : `hsla(${hue * 360}, 85%, 55%, 0.35)`;
        const strokeCol = isHighlighted ? '#e11d48' : `hsla(${hue * 360}, 90%, 35%, 0.6)`;

        // 1. Tapa Frontal (en x2)
        const ptsTop = [pOutTopA, pOutTopB, pInTopB, pInTopA];
        faces.push({
          pts: ptsTop,
          zDepth: ptsTop.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
          fill: fillCol,
          stroke: strokeCol
        });

        // 2. Pared Exterior (Cilindro R)
        const ptsOut = [pOutBotA, pOutBotB, pOutTopB, pOutTopA];
        faces.push({
          pts: ptsOut,
          zDepth: ptsOut.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
          fill: fillCol,
          stroke: strokeCol
        });

        // 3. Pared Interior (Cilindro r) si r_val > 0
        if (r_val > 0.001) {
          const ptsIn = [pInBotA, pInTopA, pInTopB, pInBotB];
          faces.push({
            pts: ptsIn,
            zDepth: ptsIn.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
            fill: fillCol,
            stroke: strokeCol
          });
        }

        // 4. Caras laterales del corte si theta < 360°
        if (maxTheta < 2 * Math.PI - 0.05) {
          if (j === 0) {
            const ptsStartCut = [pInBotA, pOutBotA, pOutTopA, pInTopA];
            faces.push({
              pts: ptsStartCut,
              zDepth: ptsStartCut.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
              fill: fillCol,
              stroke: strokeCol
            });
          }
          if (j === numAng - 1) {
            const ptsEndCut = [pInBotB, pInTopB, pOutTopB, pOutBotB];
            faces.push({
              pts: ptsEndCut,
              zDepth: ptsEndCut.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
              fill: fillCol,
              stroke: strokeCol
            });
          }
        }
      }
    }

    // Ordenar polígonos del más lejano al más cercano
    faces.sort((a, b) => a.zDepth - b.zDepth);

    // Renderizado en canvas
    faces.forEach(face => {
      ctx.save();
      ctx.beginPath();
      face.pts.forEach((pt3D, idx) => {
        const pt2D = project3D(pt3D.x, pt3D.y, pt3D.z);
        if (idx === 0) ctx.moveTo(pt2D.px, pt2D.py);
        else ctx.lineTo(pt2D.px, pt2D.py);
      });
      ctx.closePath();
      ctx.fillStyle = face.fill;
      ctx.fill();
      ctx.strokeStyle = face.stroke;
      ctx.lineWidth = 0.8;
      ctx.stroke();
      ctx.restore();
    });
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawGrid3D();
    drawAxes3D();
    drawBaseRegionXY();

    drawWashersYc3D();

    // Posición de etiquetas KaTeX flotantes
    const posUpper = project3D(2.0, f_curve(2.0), 0);
    const posLower = project3D(2.5, g_curve(2.5), 0);

    if (lblBase)  { lblBase.style.left  = posUpper.px + 'px'; lblBase.style.top  = (posUpper.py - 12) + 'px'; }
    if (lblLower) { lblLower.style.left = posLower.px + 'px'; lblLower.style.top = (posLower.py + 14) + 'px'; }

    // Actualizar Panel Overlay KaTeX
    if (infoOverlay) {
      const titleMode = mode === 'arandela' ? `Arandelas (Eje y = ${axisC.toFixed(1)})` : `Discos Macizos (Eje y = ${axisC.toFixed(1)})`;
      const V_val = getVExact();

      let phaseNote = axisC > 2.0 ? 'Fase 2: c > 2 (Eje arriba)' : (axisC < 0.0 ? 'Fase 1: c < 0 (Eje abajo)' : 'Eje dentro del intervalo');

      infoOverlay.innerHTML = `
        <div style="color: #0284c7; font-weight: 700; margin-bottom: 2px;">${titleMode}</div>
        <div style="color: #475569; font-size: 11px; font-weight: 600; margin-bottom: 3px;">${phaseNote}</div>
        <div style="color: #334155; font-size: 12px; margin-bottom: 3px;">\\(f(x) = \\sqrt{x},\\, g(x) = \\frac{x}{2},\\, x \\in [0, 4]\\)</div>
        <div style="color: #e11d48; font-weight: 700; font-size: 12px;">Volumen: \\(V = ${(V_val / Math.PI).toFixed(2)}\\pi\\)</div>
      `;

      if (window.renderMathInElement) {
        window.renderMathInElement(infoOverlay, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }

  // Cambio de Modo (Arandela vs Disco)
  btnArandela.onclick = () => {
    mode = 'arandela';
    btnArandela.style.background = '#0284c7'; btnArandela.style.color = '#ffffff';
    btnDisco.style.background = '#f1f5f9'; btnDisco.style.color = '#334155';
    draw();
  };

  btnDisco.onclick = () => {
    mode = 'disco';
    btnArandela.style.background = '#f1f5f9'; btnArandela.style.color = '#334155';
    btnDisco.style.background = '#0284c7'; btnDisco.style.color = '#ffffff';
    draw();
  };

  // Sliders
  sliderC.addEventListener('input', (e) => {
    axisC = parseFloat(e.target.value);
    valC.textContent = axisC.toFixed(1);
    draw();
  });

  sliderN.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    numN = parseInt(e.target.value);
    valN.textContent = numN;
    sweepIndex = numN;
    draw();
  });

  sliderTheta.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    thetaDeg = parseFloat(e.target.value);
    valTheta.textContent = thetaDeg + '°';
    draw();
  });

  // Animación de barrido
  function animateSweep() {
    if (isAnimating) {
      stopAnimation();
      return;
    }

    isAnimating = true;
    btnAnim.innerHTML = '⏸ Pausar';
    sweepIndex = 1;

    function stepAnim() {
      if (!isAnimating) return;
      draw();
      sweepIndex++;
      if (sweepIndex > numN) {
        stopAnimation();
        sweepIndex = numN;
        draw();
        return;
      }
      setTimeout(() => { animId = requestAnimationFrame(stepAnim); }, 140);
    }

    stepAnim();
  }

  function stopAnimation() {
    isAnimating = false;
    if (animId) cancelAnimationFrame(animId);
    btnAnim.innerHTML = '▶ Barrido 3D';
  }

  btnAnim.onclick = animateSweep;

  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - prevMousePos.x;
    const deltaY = e.clientY - prevMousePos.y;

    yaw += deltaX * 0.008;
    pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));

    prevMousePos = { x: e.clientX, y: e.clientY };
    draw();
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });

  // Zoom con Rueda
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const oldZoom = zoom;
    let newZoom = oldZoom;

    if (e.deltaY < 0) newZoom = Math.min(3.5, oldZoom * 1.08);
    else newZoom = Math.max(0.3, oldZoom / 1.08);

    if (e.shiftKey) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const scaleRatio = newZoom / oldZoom;
      const originX = (canvas.width / 2) + panX;
      const originY = (canvas.height / 2) + panY;

      panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
      panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2);
    }

    zoom = newZoom;
    draw();
  }, { passive: false });

  // Traslación con Flechas
  window.addEventListener('keydown', (e) => {
    if (document.activeElement === sliderN || document.activeElement === sliderTheta || document.activeElement === sliderC) return;
    const step = 15;
    if (e.key === 'ArrowLeft') { panX -= step; draw(); }
    else if (e.key === 'ArrowRight') { panX += step; draw(); }
    else if (e.key === 'ArrowUp') { panY -= step; draw(); }
    else if (e.key === 'ArrowDown') { panY += step; draw(); }
  });

  // Botones de Vistas Ortogonales
  document.getElementById('btnVX_arandelaYc').onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
  document.getElementById('btnVY_arandelaYc').onclick = () => { yaw = 0; pitch = 0; draw(); };
  document.getElementById('btnVZ_arandelaYc').onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };
  document.getElementById('btnReset_arandelaYc').onclick = () => {
    yaw = -0.65; pitch = 0.45; zoom = 1.0; panX = 0; panY = 0; draw();
  };

  // Pantalla Completa Adaptativa 100%
  document.getElementById('btnFS_arandelaYc').onclick = () => {
    if (!document.fullscreenElement) {
      if (container.requestFullscreen) container.requestFullscreen();
      else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
    } else {
      if (document.exitFullscreen) document.exitFullscreen();
    }
  };

  function updateCanvasSize() {
    if (document.fullscreenElement) {
      container.style.width = '100vw';
      container.style.height = '100vh';
      container.style.borderRadius = '0';
      container.style.padding = '16px';
      container.style.display = 'flex';
      container.style.flexDirection = 'column';
      container.style.justifyContent = 'space-between';

      const controlsHeight = 130;
      wrapper.style.width = '100%';
      wrapper.style.height = `${window.innerHeight - controlsHeight}px`;

      canvas.width = wrapper.clientWidth;
      canvas.height = window.innerHeight - controlsHeight;
    } else {
      container.style.width = '';
      container.style.height = '';
      container.style.borderRadius = '16px';
      container.style.padding = '16px';
      container.style.display = 'inline-block';

      wrapper.style.width = '620px';
      wrapper.style.height = '400px';

      canvas.width = 620;
      canvas.height = 400;
    }
    draw();
  }

  document.addEventListener('fullscreenchange', updateCanvasSize);
  window.addEventListener('resize', updateCanvasSize);

  draw();
})();
</script>
\end{html}

\begin{definicion}{Volumen de un Sólido de Revolución: Método de las Arandelas (Eje x = a)}
Dadas dos funciones continuas $f(y)$ y $g(y)$ en el intervalo $[c, d]$ con $f(y) \geq g(y)$, la región plana $R$ delimitada por ambas curvas gira alrededor de una recta vertical $x = a$ (eje de revolución paralelo al eje $Y$):

1. \textbf{Fase 1: Eje a la izquierda de la región}
   El radio exterior mide la distancia a la curva derecha $f(y)$ y el interior a la curva izquierda $g(y)$:
   $$R(y) = f(y) - a, \quad r(y) = g(y) - a$$
   $$V = \pi \int_{c}^{d} \left( [f(y) - a]^2 - [g(y) - a]^2 \right) dy$$

2. \textbf{Fase 2: Eje a la derecha de la región}
   El radio exterior mide la distancia a la curva izquierda $g(y)$ y el interior a la curva derecha $f(y)$:
   $$R(y) = a - g(y), \quad r(y) = a - f(y)$$
   $$V = \pi \int_{c}^{d} \left( [a - g(y)]^2 - [a - f(y)]^2 \right) dy$$
\end{definicion}

