<script>
(function() {
  const container = document.getElementById('containerArandelas3D');
  const wrapper = document.getElementById('wrapperArandelas3D');
  const canvas = document.getElementById('canvasArandelas3D');
  const ctx = canvas.getContext('2d');
  const sliderN = document.getElementById('sliderN_aran');
  const valN = document.getElementById('valN_aran');
  const sliderRot = document.getElementById('sliderRot_aran');
  const valRot = document.getElementById('valRot_aran');
  const infoOverlay = document.getElementById('infoArandelas3D');
  const btnAnim = document.getElementById('btnAnim_aran');

  const btnWasher = document.getElementById('btnModeWasher');
  const btnDisk   = document.getElementById('btnModeDisk');

  // Etiquetas KaTeX flotantes
  const lblRx = document.getElementById('labelRx_aran');
  const lblrx = document.getElementById('labelrx_aran');

  // Estado del modelo
  let modeType = 'washer'; // 'washer' (arandelas) o 'disk' (discos)
  let numN = parseInt(sliderN.value);
  let rotDeg = parseFloat(sliderRot.value);
  let sweepIndex = numN;
  let isAnimating = false;
  let animId = null;

  // Cámara (Estándar 1 Oficial)
  let yaw = -0.65;
  let pitch = 0.45;
  let zoom = 1.0;
  let panX = 0;
  let panY = 0;

  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };

  // Proyección 3D a 2D
  function project3D(x, y, z) {
    const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
    const x1 = x * cosY - y * sinY;
    const y1 = x * sinY + y * cosY;
    const z1 = z;

    const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
    const x2 = x1;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;

    const currentScale = 35 * zoom;
    const cx = canvas.width / 2 + panX;
    const cy = canvas.height / 2 + panY;

    return {
      px: cx + x2 * currentScale,
      py: cy - z2 * currentScale,
      zDepth: y2
    };
  }

  function drawLine3D(pA, pB, color, width = 1.5, dash = []) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    ctx.save();
    ctx.beginPath();
    ctx.setLineDash(dash);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();
    ctx.restore();
  }

  function drawVector3D(pA, pB, color, width = 2) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    const dx = b.px - a.px;
    const dy = b.py - a.py;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) return;

    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();

    const angle = Math.atan2(dy, dx);
    const headLen = 9;
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.moveTo(b.px, b.py);
    ctx.lineTo(b.px - headLen * Math.cos(angle - Math.PI / 6), b.py - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(b.px - headLen * Math.cos(angle + Math.PI / 6), b.py - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawGrid3D() {
    ctx.beginPath();
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = -1; i <= 5; i++) {
      const pA1 = project3D(i, -1, 0), pA2 = project3D(i, 5, 0);
      ctx.moveTo(pA1.px, pA1.py); ctx.lineTo(pA2.px, pA2.py);

      const pB1 = project3D(-1, i, 0), pB2 = project3D(5, i, 0);
      ctx.moveTo(pB1.px, pB1.py); ctx.lineTo(pB2.px, pB2.py);
    }
    ctx.stroke();
  }

  function drawAxes3D() {
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, { x: 5.2, y: 0, z: 0 }, '#000000', 2.0); // Eje X (Eje de Revolución)
    drawVector3D(O, { x: 0, y: 5.2, z: 0 }, '#000000', 2.0); // Eje Y
    drawVector3D(O, { x: 0, y: 0, z: 5.2 }, '#000000', 2.0); // Eje Z

    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#000000';
    const px = project3D(5.5, 0, 0);
    const py = project3D(0, 5.5, 0);
    const pz = project3D(0, 0, 5.5);

    ctx.fillText('x', px.px, px.py);
    ctx.fillText('y', py.px, py.py);
    ctx.fillText('z', pz.px, pz.py);

    // Graduación Eje Z
    for (let zVal = 1; zVal <= 5; zVal++) {
      const ptZ = project3D(0, 0, zVal);
      const ptTick = project3D(0.12, 0, zVal);

      ctx.save();
      ctx.beginPath();
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 1.2;
      ctx.moveTo(ptZ.px, ptZ.py);
      ctx.lineTo(ptTick.px, ptTick.py);
      ctx.stroke();

      ctx.font = '10px sans-serif';
      ctx.fillStyle = '#334155';
      ctx.fillText(zVal.toString(), ptTick.px + 4, ptTick.py + 3);
      ctx.restore();
    }
  }

  // Radios R(x) y r(x)
  function getR(x) { return Math.sqrt(x); }
  function getr(x) { return modeType === 'disk' ? 0 : x / 2.0; }

  // Dibujar curvas 2D generadoras en el plano xy
  function draw2DCurves() {
    const steps = 40;
    ctx.save();

    // Curva Externa R(x) = sqrt(x)
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const x = (i / steps) * 4.0;
      const y = getR(x);
      const p2D = project3D(x, y, 0);
      if (i === 0) ctx.moveTo(p2D.px, p2D.py);
      else ctx.lineTo(p2D.px, p2D.py);
    }
    ctx.strokeStyle = '#0284c7';
    ctx.lineWidth = 2.2;
    ctx.stroke();

    // Curva Interna r(x) = x/2
    if (modeType === 'washer') {
      ctx.beginPath();
      for (let i = 0; i <= steps; i++) {
        const x = (i / steps) * 4.0;
        const y = getr(x);
        const p2D = project3D(x, y, 0);
        if (i === 0) ctx.moveTo(p2D.px, p2D.py);
        else ctx.lineTo(p2D.px, p2D.py);
      }
      ctx.strokeStyle = '#d97706';
      ctx.lineWidth = 2.2;
      ctx.stroke();
    }

    ctx.restore();
  }

  // Dibujar las N arandelas extruidas giradas alrededor del eje X
  function drawWashers() {
    const dx = 4.0 / numN;
    const maxK = Math.min(numN, sweepIndex);
    const radMax = (rotDeg * Math.PI) / 180.0;
    const stepsPhi = 20;

    for (let k = 0; k < maxK; k++) {
      const xA = k * dx;
      const xB = (k + 1) * dx;

      const BigR_A = getR(xA), smallR_A = getr(xA);
      const BigR_B = getR(xB), smallR_B = getr(xB);

      const isHighlighted = (k === maxK - 1 && isAnimating);

      ctx.save();

      const ringOuterA = [], ringOuterB = [];
      const ringInnerA = [], ringInnerB = [];

      for (let i = 0; i <= stepsPhi; i++) {
        const phi = (i / stepsPhi) * radMax;
        const cosP = Math.cos(phi), sinP = Math.sin(phi);

        ringOuterA.push(project3D(xA, BigR_A * cosP, BigR_A * sinP));
        ringOuterB.push(project3D(xB, BigR_B * cosP, BigR_B * sinP));

        ringInnerA.push(project3D(xA, smallR_A * cosP, smallR_A * sinP));
        ringInnerB.push(project3D(xB, smallR_B * cosP, smallR_B * sinP));
      }

      // Dibujar cara anular frontal A
      ctx.beginPath();
      ringOuterA.forEach((pt, idx) => {
        if (idx === 0) ctx.moveTo(pt.px, pt.py);
        else ctx.lineTo(pt.px, pt.py);
      });
      if (modeType === 'washer') {
        for (let idx = stepsPhi; idx >= 0; idx--) {
          ctx.lineTo(ringInnerA[idx].px, ringInnerA[idx].py);
        }
      }
      ctx.closePath();
      ctx.fillStyle = isHighlighted ? 'rgba(225, 29, 72, 0.45)' : 'rgba(56, 189, 248, 0.22)';
      ctx.fill();
      ctx.strokeStyle = isHighlighted ? '#e11d48' : 'rgba(2, 132, 199, 0.5)';
      ctx.lineWidth = 0.8;
      ctx.stroke();

      // Dibujar pared cilíndrica exterior extruida
      for (let i = 0; i < stepsPhi; i++) {
        ctx.beginPath();
        ctx.moveTo(ringOuterA[i].px, ringOuterA[i].py);
        ctx.lineTo(ringOuterA[i + 1].px, ringOuterA[i + 1].py);
        ctx.lineTo(ringOuterB[i + 1].px, ringOuterB[i + 1].py);
        ctx.lineTo(ringOuterB[i].px, ringOuterB[i].py);
        ctx.closePath();
        ctx.fillStyle = isHighlighted ? 'rgba(225, 29, 72, 0.35)' : 'rgba(56, 189, 248, 0.15)';
        ctx.fill();
        ctx.stroke();
      }

      ctx.restore();
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawGrid3D();
    drawAxes3D();
    draw2DCurves();
    drawWashers();

    // Posición de etiquetas KaTeX flotantes
    const posRx = project3D(2.5, getR(2.5), 0);
    const posrx = project3D(2.5, getr(2.5), 0);

    if (lblRx) { lblRx.style.left = posRx.px + 'px'; lblRx.style.top = (posRx.py - 12) + 'px'; }
    if (lblrx) {
      if (modeType === 'washer') {
        lblrx.style.display = 'block';
        lblrx.style.left = posrx.px + 'px'; lblrx.style.top = (posrx.py - 12) + 'px';
      } else {
        lblrx.style.display = 'none';
      }
    }

    // Actualizar Panel Overlay KaTeX
    if (infoOverlay) {
      let areaFormula = '', volExact = '';
      if (modeType === 'washer') {
        areaFormula = '\\(A(x) = \\pi [R(x)^2 - r(x)^2] = \\pi \\left(x - \\frac{x^2}{4}\\right)\\)';
        volExact = '\\(V = \\pi \\int_0^4 \\left(x - \\frac{x^2}{4}\\right) dx = \\frac{8\\pi}{3} \\approx 8.38\\)';
      } else {
        areaFormula = '\\(A(x) = \\pi [R(x)]^2 = \\pi x\\)';
        volExact = '\\(V = \\pi \\int_0^4 x \\, dx = 8\\pi \\approx 25.13\\)';
      }

      infoOverlay.innerHTML = `
        <div style="color: #0284c7; font-weight: 700; margin-bottom: 3px;">Sólidos de Revolución (Eje X)</div>
        <div style="color: #334155; font-size: 12px;">Área Transversal: ${areaFormula}</div>
        <div style="color: #e11d48; font-weight: 700; font-size: 12px; margin-top: 3px;">Volumen Exacto: ${volExact}</div>
        <div style="color: #64748b; font-size: 11px; margin-top: 2px;">Arandelas de Riemann: \\(N = ${numN}\\) (\\(\\Delta x = ${(4.0/numN).toFixed(2)}\\))</div>
      `;

      if (window.renderMathInElement) {
        window.renderMathInElement(infoOverlay, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }

  // Eventos de botones de modo
  btnWasher.onclick = () => {
    modeType = 'washer';
    btnWasher.style.background = '#0284c7'; btnWasher.style.color = '#ffffff';
    btnDisk.style.background = '#f1f5f9'; btnDisk.style.color = '#334155';
    draw();
  };

  btnDisk.onclick = () => {
    modeType = 'disk';
    btnWasher.style.background = '#f1f5f9'; btnWasher.style.color = '#334155';
    btnDisk.style.background = '#0284c7'; btnDisk.style.color = '#ffffff';
    draw();
  };

  // Sliders N y Rotación
  sliderN.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    numN = parseInt(e.target.value);
    valN.textContent = numN;
    sweepIndex = numN;
    draw();
  });

  sliderRot.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    rotDeg = parseFloat(e.target.value);
    valRot.textContent = rotDeg + '°';
    draw();
  });

  // Animación de barrido
  function animateSweep() {
    if (isAnimating) {
      stopAnimation();
      return;
    }

    isAnimating = true;
    btnAnim.innerHTML = '⏸ Pausar';
    sweepIndex = 1;

    function stepAnim() {
      if (!isAnimating) return;
      draw();
      sweepIndex++;
      if (sweepIndex > numN) {
        stopAnimation();
        sweepIndex = numN;
        draw();
        return;
      }
      setTimeout(() => { animId = requestAnimationFrame(stepAnim); }, 120);
    }

    stepAnim();
  }

  function stopAnimation() {
    isAnimating = false;
    if (animId) cancelAnimationFrame(animId);
    btnAnim.innerHTML = '▶ Barrido 3D';
  }

  btnAnim.onclick = animateSweep;

  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - prevMousePos.x;
    const deltaY = e.clientY - prevMousePos.y;

    yaw += deltaX * 0.008;
    pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));

    prevMousePos = { x: e.clientX, y: e.clientY };
    draw();
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });

  // Zoom con Rueda
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const oldZoom = zoom;
    let newZoom = oldZoom;

    if (e.deltaY < 0) newZoom = Math.min(3.5, oldZoom * 1.08);
    else newZoom = Math.max(0.3, oldZoom / 1.08);

    if (e.shiftKey) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const scaleRatio = newZoom / oldZoom;
      const originX = (canvas.width / 2) + panX;
      const originY = (canvas.height / 2) + panY;

      panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
      panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2);
    }

    zoom = newZoom;
    draw();
  }, { passive: false });

  // Traslación con Flechas
  window.addEventListener('keydown', (e) => {
    if (document.activeElement === sliderN || document.activeElement === sliderRot) return;
    const step = 15;
    if (e.key === 'ArrowLeft') { panX -= step; draw(); }
    else if (e.key === 'ArrowRight') { panX += step; draw(); }
    else if (e.key === 'ArrowUp') { panY -= step; draw(); }
    else if (e.key === 'ArrowDown') { panY += step; draw(); }
  });

  // Botones de Vistas Ortogonales
  document.getElementById('btnVX_aran').onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
  document.getElementById('btnVY_aran').onclick = () => { yaw = 0; pitch = 0; draw(); };
  document.getElementById('btnVZ_aran').onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };
  document.getElementById('btnReset_aran').onclick = () => {
    yaw = -0.65; pitch = 0.45; zoom = 1.0; panX = 0; panY = 0; draw();
  };

  // Pantalla Completa Adaptativa 100%
  document.getElementById('btnFS_aran').onclick = () => {
    if (!document.fullscreenElement) {
      if (container.requestFullscreen) container.requestFullscreen();
      else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
    } else {
      if (document.exitFullscreen) document.exitFullscreen();
    }
  };

  function updateCanvasSize() {
    if (document.fullscreenElement) {
      container.style.width = '100vw';
      container.style.height = '100vh';
      container.style.borderRadius = '0';
      container.style.padding = '16px';
      container.style.display = 'flex';
      container.style.flexDirection = 'column';
      container.style.justifyContent = 'space-between';

      const controlsHeight = 130;
      wrapper.style.width = '100%';
      wrapper.style.height = `${window.innerHeight - controlsHeight}px`;

      canvas.width = wrapper.clientWidth;
      canvas.height = window.innerHeight - controlsHeight;
    } else {
      container.style.width = '';
      container.style.height = '';
      container.style.borderRadius = '16px';
      container.style.padding = '16px';
      container.style.display = 'inline-block';

      wrapper.style.width = '620px';
      wrapper.style.height = '400px';

      canvas.width = 620;
      canvas.height = 400;
    }
    draw();
  }

  document.addEventListener('fullscreenchange', updateCanvasSize);
  window.addEventListener('resize', updateCanvasSize);

  draw();
})();
</script>
