<script>
(function() {
  const container = document.getElementById('containerArandelasY3D');
  const wrapper = document.getElementById('wrapperArandelasY3D');
  const canvas = document.getElementById('canvasArandelasY3D');
  const ctx = canvas.getContext('2d');

  const sliderN = document.getElementById('sliderN_arandelaY');
  const valN = document.getElementById('valN_arandelaY');
  const sliderTheta = document.getElementById('sliderTheta_arandelaY');
  const valTheta = document.getElementById('valTheta_arandelaY');

  const infoOverlay = document.getElementById('infoArandelasY3D');
  const btnAnim = document.getElementById('btnAnim_arandelaY');

  const btnArandela = document.getElementById('btnModeArandela');
  const btnDisco = document.getElementById('btnModeDisco');

  // Etiquetas KaTeX flotantes
  const lblBase = document.getElementById('labelBase_arandelaY');
const lblInt = document.getElementById('labelInt_arandelaY');
  const lblSlice = document.getElementById('labelSlice_arandelaY');

  // Modo: 'arandela' o 'disco'
  let mode = 'arandela';

  // Dominio en Y: y in [0, 4]
  const c = 0.0;
  const d = 4.0;

  // Radio exterior R(y) = 2*sqrt(y) para AMBOS MODOS
  function R_ext(y) {
    return 2.0 * Math.sqrt(Math.max(0, y));
  }
  // Radio interior r(y) = y para Arandelas, 0 para Discos
  function r_int(y) {
    return mode === 'arandela' ? y : 0.0;
  }

  function getVExact() {
    // Arandelas: pi * integral_0^4 (4y - y^2) dy = 32*pi/3 ≈ 33.5103
    // Discos: pi * integral_0^4 4y dy = 32*pi ≈ 100.5310
    return mode === 'arandela' ? (32.0 * Math.PI) / 3.0 : 32.0 * Math.PI;
  }

  let numN = parseInt(sliderN.value);
  let thetaDeg = parseFloat(sliderTheta.value);
  let sweepIndex = numN;
  let isAnimating = false;
  let animId = null;

  // Cámara (Estándar 1 y 2 Oficial)
  let yaw = -0.65;
  let pitch = 0.45;
  let zoom = 1.0;
  let panX = 0;
  let panY = 0;

  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };

  // Proyección 3D a 2D (Software Engine Canvas 2D)
  function project3D(x, y, z) {
    const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
    const x1 = x * cosY - y * sinY;
    const y1 = x * sinY + y * cosY;
    const z1 = z;

    const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
    const x2 = x1;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;

    const currentScale = 32 * zoom;
    const cx = canvas.width / 2 + panX;
    const cy = canvas.height / 2 + panY + 20;

    return {
      px: cx + x2 * currentScale,
      py: cy - z2 * currentScale,
      zDepth: y2
    };
  }

  function drawVector3D(pA, pB, color, width = 2) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    const dx = b.px - a.px;
    const dy = b.py - a.py;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) return;

    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();

    const angle = Math.atan2(dy, dx);
    const headLen = 9;
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.moveTo(b.px, b.py);
    ctx.lineTo(b.px - headLen * Math.cos(angle - Math.PI / 6), b.py - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(b.px - headLen * Math.cos(angle + Math.PI / 6), b.py - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // REJILLA/CUADRICULADO EN Z=0
  function drawGrid3D() {
    ctx.beginPath();
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1.0;
    const minVal = -4;
    const maxVal = 5;

    // 1. Líneas paralelas al Eje Y (x constante)
    for (let x = minVal; x <= maxVal; x++) {
      const pA = project3D(x, minVal, 0);
      const pB = project3D(x, maxVal, 0);
      ctx.moveTo(pA.px, pA.py);
      ctx.lineTo(pB.px, pB.py);
    }

    // 2. Líneas paralelas al Eje X (y constante)
    for (let y = minVal; y <= maxVal; y++) {
      const pA = project3D(minVal, y, 0);
      const pB = project3D(maxVal, y, 0);
      ctx.moveTo(pA.px, pA.py);
      ctx.lineTo(pB.px, pB.py);
    }
    ctx.stroke();
  }

  function drawAxes3D() {
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, { x: 5.0, y: 0, z: 0 }, '#000000', 2.0); // Eje X
    drawVector3D(O, { x: 0, y: 5.0, z: 0 }, '#000000', 2.0); // Eje Y (Eje de Revolución)
    drawVector3D(O, { x: 0, y: 0, z: 5.0 }, '#000000', 2.0); // Eje Z

    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#000000';
    const px = project3D(5.3, 0, 0);
    const py = project3D(0, 5.3, 0);
    const pz = project3D(0, 0, 5.3);

    ctx.fillText('x', px.px, px.py);
    ctx.fillText('y', py.px - 20, py.py - 10);
    ctx.fillText('z', pz.px, pz.py);

    // Graduación Eje Y
    for (let yVal = 1; yVal <= 4; yVal++) {
      const ptY = project3D(0, yVal, 0);
      const ptTick = project3D(0.12, yVal, 0);

      ctx.save();
      ctx.beginPath();
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 1.2;
      ctx.moveTo(ptY.px, ptY.py);
      ctx.lineTo(ptTick.px, ptTick.py);
      ctx.stroke();

      ctx.font = '10px sans-serif';
      ctx.fillStyle = '#334155';
      ctx.fillText(yVal.toString(), ptTick.px + 4, ptTick.py + 3);
      ctx.restore();
    }
  }

  // Dibujar curvas frontera de la región plana en el plano XY (z=0)
  function drawBaseRegionXY() {
    const steps = 40;
    ctx.save();

    // R_ext en azul
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const yVal = c + (i / steps) * (d - c);
      const xVal = R_ext(yVal);
      const pt = project3D(xVal, yVal, 0);
      if (i === 0) ctx.moveTo(pt.px, pt.py);
      else ctx.lineTo(pt.px, pt.py);
    }
    // Retorno por r_int en verde
    for (let i = steps; i >= 0; i--) {
      const yVal = c + (i / steps) * (d - c);
      const xVal = r_int(yVal);
      const pt = project3D(xVal, yVal, 0);
      ctx.lineTo(pt.px, pt.py);
    }
    ctx.closePath();
    ctx.fillStyle = 'rgba(2, 132, 199, 0.12)';
    ctx.fill();

    // Trazo de R_ext (Azul)
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const yVal = c + (i / steps) * (d - c);
      const pt = project3D(R_ext(yVal), yVal, 0);
      if (i === 0) ctx.moveTo(pt.px, pt.py);
      else ctx.lineTo(pt.px, pt.py);
    }
    ctx.strokeStyle = '#0284c7';
    ctx.lineWidth = 2.0;
    ctx.stroke();

    // Trazo de r_int (Verde) si es arandela
    if (mode === 'arandela') {
      ctx.beginPath();
      for (let i = 0; i <= steps; i++) {
        const yVal = c + (i / steps) * (d - c);
        const pt = project3D(r_int(yVal), yVal, 0);
        if (i === 0) ctx.moveTo(pt.px, pt.py);
        else ctx.lineTo(pt.px, pt.py);
      }
      ctx.strokeStyle = '#059669';
      ctx.lineWidth = 2.0;
      ctx.stroke();
    }

    ctx.restore();
  }

  // Dibujar Arandelas / Discos en 3D perpendiculares al Eje Y (Painter's Algorithm)
  function drawWashers3D() {
    const maxTheta = (thetaDeg * Math.PI) / 180.0;
    const dy = (d - c) / numN;
    const maxK = Math.min(numN, sweepIndex);

    const faces = [];
    const numAng = Math.max(16, Math.floor(24 * (maxTheta / (2 * Math.PI))));

    let sumVN = 0.0;
    const V_exact = getVExact();

    for (let k = 0; k < maxK; k++) {
      const y1 = c + k * dy;
      const y2 = c + (k + 1) * dy;
      const yMid = (y1 + y2) / 2.0;

      const R_val = R_ext(yMid);
      const r_val = r_int(yMid);

      sumVN += Math.PI * (R_val * R_val - r_val * r_val) * dy * (maxTheta / (2 * Math.PI));

      if (R_val <= 0.001) continue;

      const isHighlighted = (k === maxK - 1 && isAnimating);

      for (let j = 0; j < numAng; j++) {
        const thA = (j / numAng) * maxTheta;
        const thB = ((j + 1) / numAng) * maxTheta;

        const cosA = Math.cos(thA), sinA = Math.sin(thA);
        const cosB = Math.cos(thB), sinB = Math.sin(thB);

        const pOutBotA = { x: R_val * cosA, y: y1, z: R_val * sinA };
        const pOutBotB = { x: R_val * cosB, y: y1, z: R_val * sinB };
        const pOutTopB = { x: R_val * cosB, y: y2, z: R_val * sinB };
        const pOutTopA = { x: R_val * cosA, y: y2, z: R_val * sinA };

        const pInBotA = { x: r_val * cosA, y: y1, z: r_val * sinA };
        const pInBotB = { x: r_val * cosB, y: y1, z: r_val * sinB };
        const pInTopB = { x: r_val * cosB, y: y2, z: r_val * sinB };
        const pInTopA = { x: r_val * cosA, y: y2, z: r_val * sinA };

        const hue = 0.95 - (k / numN) * 0.15;
        const fillCol = isHighlighted ? 'rgba(225, 29, 72, 0.55)' : `hsla(${hue * 360}, 85%, 55%, 0.35)`;
        const strokeCol = isHighlighted ? '#e11d48' : `hsla(${hue * 360}, 90%, 35%, 0.6)`;

        // 1. Tapa Superior (en y2)
        const ptsTop = [pOutTopA, pOutTopB, pInTopB, pInTopA];
        faces.push({
          pts: ptsTop,
          zDepth: ptsTop.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
          fill: fillCol,
          stroke: strokeCol
        });

        // 2. Pared Exterior (Cilindro R)
        const ptsOut = [pOutBotA, pOutBotB, pOutTopB, pOutTopA];
        faces.push({
          pts: ptsOut,
          zDepth: ptsOut.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
          fill: fillCol,
          stroke: strokeCol
        });

        // 3. Pared Interior (Cilindro r) si r_val > 0
        if (r_val > 0.001) {
          const ptsIn = [pInBotA, pInTopA, pInTopB, pInBotB];
          faces.push({
            pts: ptsIn,
            zDepth: ptsIn.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
            fill: fillCol,
            stroke: strokeCol
          });
        }

        // 4. Caras laterales del corte si theta < 360°
        if (maxTheta < 2 * Math.PI - 0.05) {
          if (j === 0) {
            const ptsStartCut = [pInBotA, pOutBotA, pOutTopA, pInTopA];
            faces.push({
              pts: ptsStartCut,
              zDepth: ptsStartCut.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
              fill: fillCol,
              stroke: strokeCol
            });
          }
          if (j === numAng - 1) {
            const ptsEndCut = [pInBotB, pInTopB, pOutTopB, pOutBotB];
            faces.push({
              pts: ptsEndCut,
              zDepth: ptsEndCut.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
              fill: fillCol,
              stroke: strokeCol
            });
          }
        }
      }
    }

    // Ordenar polígonos del más lejano al más cercano
    faces.sort((a, b) => a.zDepth - b.zDepth);

    // Renderizado en canvas
    faces.forEach(face => {
      ctx.save();
      ctx.beginPath();
      face.pts.forEach((pt3D, idx) => {
        const pt2D = project3D(pt3D.x, pt3D.y, pt3D.z);
        if (idx === 0) ctx.moveTo(pt2D.px, pt2D.py);
        else ctx.lineTo(pt2D.px, pt2D.py);
      });
      ctx.closePath();
      ctx.fillStyle = face.fill;
      ctx.fill();
      ctx.strokeStyle = face.stroke;
      ctx.lineWidth = 0.8;
      ctx.stroke();
      ctx.restore();
    });

    return { sumVN, V_exact };
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawGrid3D();
    drawAxes3D();
    drawBaseRegionXY();

    const { sumVN, V_exact } = drawWashers3D();

    // Posición de etiquetas KaTeX flotantes
    const posBase  = project3D(R_ext(2.0), 2.0, 0);



    //const posSlice = project3D(R_ext(3.0) * 0.7, 3.0, R_ext(3.0) * 0.7);


    const posInt   = project3D(r_int(2.5), 2.5, 0);
    const posSlice = project3D(R_ext(3.0) * 0.7, 3.0, R_ext(3.0) * 0.7);
    if (lblBase)  { lblBase.style.left  = posBase.px + 'px';  lblBase.style.top  = (posBase.py - 12) + 'px'; }

    if (lblInt) {
      if (mode === 'arandela') {
        lblInt.style.display = 'block';
        lblInt.style.left = posInt.px + 'px';
        lblInt.style.top  = (posInt.py - 12) + 'px';
      } else {
        lblInt.style.display = 'none';
      }
    }
    if (lblBase)  { lblBase.style.left  = posBase.px + 'px';  lblBase.style.top  = (posBase.py - 12) + 'px'; }
    if (lblSlice) { lblSlice.style.left = posSlice.px + 'px'; lblSlice.style.top = (posSlice.py - 10) + 'px'; }

    // Actualizar Panel Overlay KaTeX
    if (infoOverlay) {
      const errRel = Math.abs((sumVN - V_exact) / V_exact) * 100.0;
      const titleMode = mode === 'arandela' ? 'Método de Arandelas (Eje Y)' : 'Método de Discos Macizos (Eje Y)';
      const funcsText = mode === 'arandela' 
        ? '\\(R(y) = 2\\sqrt{y},\\, r(y) = y\\)' 
        : '\\(R(y) = 2\\sqrt{y},\\, r(y) = 0\\)';
      const formulaExact = mode === 'arandela'
        ? '\\(V = \\frac{32\\pi}{3} \\)'
        : '\\(V = 32\\pi \\approx 100.5310\\)';

      infoOverlay.innerHTML = `
        <div style="color: #0284c7; font-weight: 700; margin-bottom: 3px;">${titleMode}</div>
        <!--<div style="color: #334155; font-size: 12px;">Curvas: ${funcsText}, \\(y \\in [0, 4]\\)</div>-->
        <!--<div style="color: #059669; font-size: 12px; margin-top: 2px;">Suma de Riemann: \\(V_N = ${sumVN.toFixed(4)}\\)</div>-->
        <div style="color: #e11d48; font-weight: 700; font-size: 12px; margin-top: 3px;">Volumen: ${formulaExact}</div>
        <!--<div style="color: #d97706; font-size: 11px; margin-top: 2px; font-weight: 600;">Error Relativo: ${errRel.toFixed(2)}%</div>-->
      `;

      if (window.renderMathInElement) {
        window.renderMathInElement(infoOverlay, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }

  // Cambio de Modo (Arandela vs Disco)
  btnArandela.onclick = () => {
    mode = 'arandela';
    btnArandela.style.background = '#0284c7'; btnArandela.style.color = '#ffffff';
    btnDisco.style.background = '#f1f5f9'; btnDisco.style.color = '#334155';
    draw();
  };

  btnDisco.onclick = () => {
    mode = 'disco';
    btnArandela.style.background = '#f1f5f9'; btnArandela.style.color = '#334155';
    btnDisco.style.background = '#0284c7'; btnDisco.style.color = '#ffffff';
    draw();
  };

  // Sliders
  sliderN.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    numN = parseInt(e.target.value);
    valN.textContent = numN;
    sweepIndex = numN;
    draw();
  });

  sliderTheta.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    thetaDeg = parseFloat(e.target.value);
    valTheta.textContent = thetaDeg + '°';
    draw();
  });

  // Animación de barrido
  function animateSweep() {
    if (isAnimating) {
      stopAnimation();
      return;
    }

    isAnimating = true;
    btnAnim.innerHTML = '⏸ Pausar';
    sweepIndex = 1;

    function stepAnim() {
      if (!isAnimating) return;
      draw();
      sweepIndex++;
      if (sweepIndex > numN) {
        stopAnimation();
        sweepIndex = numN;
        draw();
        return;
      }
      setTimeout(() => { animId = requestAnimationFrame(stepAnim); }, 140);
    }

    stepAnim();
  }

  function stopAnimation() {
    isAnimating = false;
    if (animId) cancelAnimationFrame(animId);
    btnAnim.innerHTML = '▶ Barrido 3D';
  }

  btnAnim.onclick = animateSweep;

  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - prevMousePos.x;
    const deltaY = e.clientY - prevMousePos.y;

    yaw += deltaX * 0.008;
    pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));

    prevMousePos = { x: e.clientX, y: e.clientY };
    draw();
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });

  // Zoom con Rueda
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const oldZoom = zoom;
    let newZoom = oldZoom;

    if (e.deltaY < 0) newZoom = Math.min(3.5, oldZoom * 1.08);
    else newZoom = Math.max(0.3, oldZoom / 1.08);

    if (e.shiftKey) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const scaleRatio = newZoom / oldZoom;
      const originX = (canvas.width / 2) + panX;
      const originY = (canvas.height / 2) + panY;

      panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
      panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2);
    }

    zoom = newZoom;
    draw();
  }, { passive: false });

  // Traslación con Flechas
  window.addEventListener('keydown', (e) => {
    if (document.activeElement === sliderN || document.activeElement === sliderTheta) return;
    const step = 15;
    if (e.key === 'ArrowLeft') { panX -= step; draw(); }
    else if (e.key === 'ArrowRight') { panX += step; draw(); }
    else if (e.key === 'ArrowUp') { panY -= step; draw(); }
    else if (e.key === 'ArrowDown') { panY += step; draw(); }
  });

  // Botones de Vistas Ortogonales
  document.getElementById('btnVX_arandelaY').onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
  document.getElementById('btnVY_arandelaY').onclick = () => { yaw = 0; pitch = 0; draw(); };
  document.getElementById('btnVZ_arandelaY').onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };
  document.getElementById('btnReset_arandelaY').onclick = () => {
    yaw = -0.65; pitch = 0.45; zoom = 1.0; panX = 0; panY = 0; draw();
  };

  // Pantalla Completa Adaptativa 100%
  document.getElementById('btnFS_arandelaY').onclick = () => {
    if (!document.fullscreenElement) {
      if (container.requestFullscreen) container.requestFullscreen();
      else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
    } else {
      if (document.exitFullscreen) document.exitFullscreen();
    }
  };

  function updateCanvasSize() {
    if (document.fullscreenElement) {
      container.style.width = '100vw';
      container.style.height = '100vh';
      container.style.borderRadius = '0';
      container.style.padding = '16px';
      container.style.display = 'flex';
      container.style.flexDirection = 'column';
      container.style.justifyContent = 'space-between';

      const controlsHeight = 130;
      wrapper.style.width = '100%';
      wrapper.style.height = `${window.innerHeight - controlsHeight}px`;

      canvas.width = wrapper.clientWidth;
      canvas.height = window.innerHeight - controlsHeight;
    } else {
      container.style.width = '';
      container.style.height = '';
      container.style.borderRadius = '16px';
      container.style.padding = '16px';
      container.style.display = 'inline-block';

      wrapper.style.width = '620px';
      wrapper.style.height = '400px';

      canvas.width = 620;
      canvas.height = 400;
    }
    draw();
  }

  document.addEventListener('fullscreenchange', updateCanvasSize);
  window.addEventListener('resize', updateCanvasSize);

  draw();
})();
</script>
\end{html}

\begin{definicion}{Método Capas Cilíndricas al rededor eje $y$}
Sea $f: [a, b] \to \mathbb{R}$ una función continua e no negativa ($f(x) \geq 0$) en el intervalo $[a, b]$ con $0 \leq a < b$. Si la región plana $R$ delimitada por la gráfica $y = f(x)$, el eje $X$ y las rectas verticales $x = a$ y $x = b$ se hace girar alrededor del eje vertical de revolución (eje $Y$), el volumen $V$ del sólido generado mediante la acumulación de cascarones o capas cilíndricas concéntricas viene dado por:
$$V = 2\pi \int_{a}^{b} x \cdot f(x) \, dx$$
Aproximando la región por $N$ rectángulos de ancho $\Delta x = \frac{b-a}{N}$ y altura $h_i = f(x_i^*)$ en el radio medio $x_i^* = a + \left(i - \frac{1}{2}\right)\Delta x$, al rotar cada rectángulo se genera una capa cilíndrica de radio medio $x_i^*$, espesor $\Delta x$ y altura $h_i$, cuyo volumen elemental es $\Delta V_i = 2\pi x_i^* f(x_i^*) \Delta x$. La suma de Riemann convergente es:
$$V_N = \sum_{i=1}^{N} 2\pi \, x_i^* \, f(x_i^*) \, \Delta x \xrightarrow[N \to \infty]{} V$$
\end{definicion}

