<script>
(function() {
  const container = document.getElementById('containerCapas3D');
  const wrapper = document.getElementById('wrapperCapas3D');
  const canvas = document.getElementById('canvasCapas3D');
  const ctx = canvas.getContext('2d');

  const sliderN = document.getElementById('sliderN_capas');
  const valN = document.getElementById('valN_capas');
  const sliderTheta = document.getElementById('sliderTheta_capas');
  const valTheta = document.getElementById('valTheta_capas');

  const infoOverlay = document.getElementById('infoCapas3D');
  const btnAnim = document.getElementById('btnAnim_capas');

  // Etiqueta KaTeX flotante
  const lblBase = document.getElementById('labelBase_capas');

  // Modelo Geométrico: f(x) = 3x - x^2 en [0, 3]
  const a = 0.0;
  const b = 3.0;
  const f = (x) => 3.0 * x - x * x;

  let numN = parseInt(sliderN.value);
  let thetaDeg = parseFloat(sliderTheta.value);
  let sweepIndex = numN;
  let isAnimating = false;
  let animId = null;

  // Cámara (Estándar 1 y 2 Oficial)
  let yaw = -0.65;
  let pitch = 0.45;
  let zoom = 1.0;
  let panX = 0;
  let panY = 0;

  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };

  // Proyección 3D a 2D (Software Engine Canvas 2D)
  function project3D(x, y, z) {
    const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
    const x1 = x * cosY - y * sinY;
    const y1 = x * sinY + y * cosY;
    const z1 = z;

    const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
    const x2 = x1;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;

    const currentScale = 38 * zoom;
    const cx = canvas.width / 2 + panX;
    const cy = canvas.height / 2 + panY + 40;

    return {
      px: cx + x2 * currentScale,
      py: cy - z2 * currentScale,
      zDepth: y2
    };
  }

  function drawVector3D(pA, pB, color, width = 2) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    const dx = b.px - a.px;
    const dy = b.py - a.py;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) return;

    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();

    const angle = Math.atan2(dy, dx);
    const headLen = 9;
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.moveTo(b.px, b.py);
    ctx.lineTo(b.px - headLen * Math.cos(angle - Math.PI / 6), b.py - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(b.px - headLen * Math.cos(angle + Math.PI / 6), b.py - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // REJILLA/CUADRICULADO EN Z=0
  function drawGrid3D() {
    ctx.beginPath();
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1.0;
    const minVal = -4;
    const maxVal = 5;

    // 1. Líneas paralelas al Eje Y (x constante)
    for (let x = minVal; x <= maxVal; x++) {
      const pA = project3D(x, minVal, 0);
      const pB = project3D(x, maxVal, 0);
      ctx.moveTo(pA.px, pA.py);
      ctx.lineTo(pB.px, pB.py);
    }

    // 2. Líneas paralelas al Eje X (y constante)
    for (let y = minVal; y <= maxVal; y++) {
      const pA = project3D(minVal, y, 0);
      const pB = project3D(maxVal, y, 0);
      ctx.moveTo(pA.px, pA.py);
      ctx.lineTo(pB.px, pB.py);
    }
    ctx.stroke();
  }

  function drawAxes3D() {
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, { x: 4.5, y: 0, z: 0 }, '#000000', 2.0); // Eje X
    drawVector3D(O, { x: 0, y: 0, z: 4.0 }, '#000000', 2.0); // Eje Vertical (Eje Y)

    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#000000';
    const px = project3D(4.8, 0, 0);
    const pz = project3D(0, 0, 4.3);

    ctx.fillText('x', px.px, px.py);
    ctx.fillText('y', pz.px, pz.py);
  }

  // Curva generatriz y región 2D base sobre el plano XZ
  function drawBaseCurve2D() {
    const steps = 40;
    ctx.save();

    // Región plana en el plano XZ (y=0)
    ctx.beginPath();
    ctx.moveTo(project3D(0, 0, 0).px, project3D(0, 0, 0).py);
    for (let i = 0; i <= steps; i++) {
      const xVal = a + (i / steps) * (b - a);
      const zVal = f(xVal);
      const pt = project3D(xVal, 0, zVal);
      ctx.lineTo(pt.px, pt.py);
    }
    ctx.lineTo(project3D(b, 0, 0).px, project3D(b, 0, 0).py);
    ctx.closePath();
    ctx.fillStyle = 'rgba(2, 132, 199, 0.15)';
    ctx.fill();

    // Trazo de la curva f(x)
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const xVal = a + (i / steps) * (b - a);
      const zVal = f(xVal);
      const pt = project3D(xVal, 0, zVal);
      if (i === 0) ctx.moveTo(pt.px, pt.py);
      else ctx.lineTo(pt.px, pt.py);
    }
    ctx.strokeStyle = '#0284c7';
    ctx.lineWidth = 2.5;
    ctx.stroke();

    ctx.restore();
  }

  // Dibujar los N Cascarones Cilíndricos mediante Ordenamiento de Caras (Painter's Algorithm)
  function drawCylindricalShells() {
    const maxTheta = (thetaDeg * Math.PI) / 180.0;
    const dx = (b - a) / numN;
    const maxK = Math.min(numN, sweepIndex);

    const faces = [];
    const numAng = Math.max(16, Math.floor(24 * (maxTheta / (2 * Math.PI))));

    for (let k = 0; k < maxK; k++) {
      const r1 = a + k * dx;
      const r2 = a + (k + 1) * dx;
      const rMid = (r1 + r2) / 2.0;
      const hMid = f(rMid);

      if (hMid <= 0.001 || r2 <= 0.001) continue;

      const isHighlighted = (k === maxK - 1 && isAnimating);

      // Generar sectores angulares del cascarón
      for (let j = 0; j < numAng; j++) {
        const thA = (j / numAng) * maxTheta;
        const thB = ((j + 1) / numAng) * maxTheta;

        const cosA = Math.cos(thA), sinA = Math.sin(thA);
        const cosB = Math.cos(thB), sinB = Math.sin(thB);

        // Vértices 3D
        const pOutBotA = { x: r2 * cosA, y: r2 * sinA, z: 0 };
        const pOutBotB = { x: r2 * cosB, y: r2 * sinB, z: 0 };
        const pOutTopB = { x: r2 * cosB, y: r2 * sinB, z: hMid };
        const pOutTopA = { x: r2 * cosA, y: r2 * sinA, z: hMid };

        const pInBotA = { x: r1 * cosA, y: r1 * sinA, z: 0 };
        const pInBotB = { x: r1 * cosB, y: r1 * sinB, z: 0 };
        const pInTopB = { x: r1 * cosB, y: r1 * sinB, z: hMid };
        const pInTopA = { x: r1 * cosA, y: r1 * sinA, z: hMid };

        // Color según capa y resalte
        const hue = 0.54 + (k / numN) * 0.12;
        const fillCol = isHighlighted ? 'rgba(225, 29, 72, 0.45)' : `hsla(${hue * 360}, 85%, 55%, 0.35)`;
        const strokeCol = isHighlighted ? '#e11d48' : `hsla(${hue * 360}, 90%, 35%, 0.6)`;

        // 1. Tapa Superior (Anillo)
        const ptsTop = [pOutTopA, pOutTopB, pInTopB, pInTopA];
        faces.push({
          pts: ptsTop,
          zDepth: ptsTop.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
          fill: fillCol,
          stroke: strokeCol
        });

        // 2. Pared Exterior
        const ptsOut = [pOutBotA, pOutBotB, pOutTopB, pOutTopA];
        faces.push({
          pts: ptsOut,
          zDepth: ptsOut.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
          fill: fillCol,
          stroke: strokeCol
        });

        // 3. Pared Interior (si r1 > 0)
        if (r1 > 0.001) {
          const ptsIn = [pInBotA, pInTopA, pInTopB, pInBotB];
          faces.push({
            pts: ptsIn,
            zDepth: ptsIn.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
            fill: fillCol,
            stroke: strokeCol
          });
        }

        // 4. Caras laterales del corte si theta < 360°
        if (maxTheta < 2 * Math.PI - 0.05) {
          if (j === 0) {
            const ptsStartCut = [pInBotA, pOutBotA, pOutTopA, pInTopA];
            faces.push({
              pts: ptsStartCut,
              zDepth: ptsStartCut.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
              fill: fillCol,
              stroke: strokeCol
            });
          }
          if (j === numAng - 1) {
            const ptsEndCut = [pInBotB, pInTopB, pOutTopB, pOutBotB];
            faces.push({
              pts: ptsEndCut,
              zDepth: ptsEndCut.reduce((s, p) => s + project3D(p.x, p.y, p.z).zDepth, 0) / 4,
              fill: fillCol,
              stroke: strokeCol
            });
          }
        }
      }
    }

    // Ordenar polígonos del más lejano al más cercano (Painter's Algorithm)
    faces.sort((a, b) => a.zDepth - b.zDepth);

    // Dibujar polígonos proyeccionados
    faces.forEach(face => {
      ctx.save();
      ctx.beginPath();
      face.pts.forEach((pt3D, idx) => {
        const pt2D = project3D(pt3D.x, pt3D.y, pt3D.z);
        if (idx === 0) ctx.moveTo(pt2D.px, pt2D.py);
        else ctx.lineTo(pt2D.px, pt2D.py);
      });
      ctx.closePath();
      ctx.fillStyle = face.fill;
      ctx.fill();
      ctx.strokeStyle = face.stroke;
      ctx.lineWidth = 0.8;
      ctx.stroke();
      ctx.restore();
    });
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawGrid3D();
    drawAxes3D();
    drawBaseCurve2D();

    drawCylindricalShells();

    // Posición de etiqueta KaTeX flotante
    const posBase = project3D(1.5, 0, f(1.5));
    if (lblBase) { lblBase.style.left = posBase.px + 'px'; lblBase.style.top = (posBase.py - 12) + 'px'; }

    // Actualizar Panel Overlay KaTeX
    if (infoOverlay) {
      infoOverlay.innerHTML = `
        <div style="color: #0284c7; font-weight: 700; margin-bottom: 3px;">Capas Cilíndricas</div>
        <div style="color: #334155; font-size: 12px; margin-bottom: 3px;">\\(f(x) = 3x - x^2,\\quad x \\in [0, 3]\\)</div>
        <div style="color: #e11d48; font-weight: 700; font-size: 12px;">Volumen: \\(V = \\frac{27\\pi}{2}\\)</div>
      `;

      if (window.renderMathInElement) {
        window.renderMathInElement(infoOverlay, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }

  // Sliders
  sliderN.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    numN = parseInt(e.target.value);
    valN.textContent = numN;
    sweepIndex = numN;
    draw();
  });

  sliderTheta.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    thetaDeg = parseFloat(e.target.value);
    valTheta.textContent = thetaDeg + '°';
    draw();
  });

  // Animación de barrido
  function animateSweep() {
    if (isAnimating) {
      stopAnimation();
      return;
    }

    isAnimating = true;
    btnAnim.innerHTML = '⏸ Pausar';
    sweepIndex = 1;

    function stepAnim() {
      if (!isAnimating) return;
      draw();
      sweepIndex++;
      if (sweepIndex > numN) {
        stopAnimation();
        sweepIndex = numN;
        draw();
        return;
      }
      setTimeout(() => { animId = requestAnimationFrame(stepAnim); }, 140);
    }

    stepAnim();
  }

  function stopAnimation() {
    isAnimating = false;
    if (animId) cancelAnimationFrame(animId);
    btnAnim.innerHTML = '▶ Barrido 3D';
  }

  btnAnim.onclick = animateSweep;

  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - prevMousePos.x;
    const deltaY = e.clientY - prevMousePos.y;

    yaw += deltaX * 0.008;
    pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));

    prevMousePos = { x: e.clientX, y: e.clientY };
    draw();
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });

  // Zoom con Rueda
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const oldZoom = zoom;
    let newZoom = oldZoom;

    if (e.deltaY < 0) newZoom = Math.min(3.5, oldZoom * 1.08);
    else newZoom = Math.max(0.3, oldZoom / 1.08);

    if (e.shiftKey) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const scaleRatio = newZoom / oldZoom;
      const originX = (canvas.width / 2) + panX;
      const originY = (canvas.height / 2) + panY;

      panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
      panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2);
    }

    zoom = newZoom;
    draw();
  }, { passive: false });

  // Traslación con Flechas
  window.addEventListener('keydown', (e) => {
    if (document.activeElement === sliderN || document.activeElement === sliderTheta) return;
    const step = 15;
    if (e.key === 'ArrowLeft') { panX -= step; draw(); }
    else if (e.key === 'ArrowRight') { panX += step; draw(); }
    else if (e.key === 'ArrowUp') { panY -= step; draw(); }
    else if (e.key === 'ArrowDown') { panY += step; draw(); }
  });

  // Botones de Vistas Ortogonales
  document.getElementById('btnVX_capas').onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
  document.getElementById('btnVZ_capas').onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };
  document.getElementById('btnReset_capas').onclick = () => {
    yaw = -0.65; pitch = 0.45; zoom = 1.0; panX = 0; panY = 0; draw();
  };

  // Pantalla Completa Adaptativa 100%
  document.getElementById('btnFS_capas').onclick = () => {
    if (!document.fullscreenElement) {
      if (container.requestFullscreen) container.requestFullscreen();
      else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
    } else {
      if (document.exitFullscreen) document.exitFullscreen();
    }
  };

  function updateCanvasSize() {
    if (document.fullscreenElement) {
      container.style.width = '100vw';
      container.style.height = '100vh';
      container.style.borderRadius = '0';
      container.style.padding = '16px';
      container.style.display = 'flex';
      container.style.flexDirection = 'column';
      container.style.justifyContent = 'space-between';

      const controlsHeight = 130;
      wrapper.style.width = '100%';
      wrapper.style.height = `${window.innerHeight - controlsHeight}px`;

      canvas.width = wrapper.clientWidth;
      canvas.height = window.innerHeight - controlsHeight;
    } else {
      container.style.width = '';
      container.style.height = '';
      container.style.borderRadius = '16px';
      container.style.padding = '16px';
      container.style.display = 'inline-block';

      wrapper.style.width = '620px';
      wrapper.style.height = '400px';

      canvas.width = 620;
      canvas.height = 400;
    }
    draw();
  }

  document.addEventListener('fullscreenchange', updateCanvasSize);
  window.addEventListener('resize', updateCanvasSize);

  draw();
})();
</script>
\end{html}

\begin{definicion}{Volumen de un Sólido de Revolución: Método de las Capas Cilíndricas (Eje X)}
Sea $g: [c, d] \to \mathbb{R}$ una función continua e no negativa ($g(y) \geq 0$) en el intervalo $[c, d]$ con $0 \leq c < d$. Si la región plana $R$ delimitada por la gráfica $x = g(y)$, el eje $Y$ y las rectas horizontales $y = c$ y $y = d$ se hace girar alrededor del **eje horizontal de revolución (eje $X$)**, el volumen $V$ del sólido generado mediante la acumulación de cascarones cilíndricos horizontales concéntricos es:
$$V = 2\pi \int_{c}^{d} y \cdot g(y) \, dy$$
Aproximando la región por $N$ rectángulos de ancho $\Delta y = \frac{d-c}{N}$ y longitud $h_i = g(y_i^*)$ a una distancia (radio) $y_i^* = c + \left(i - \frac{1}{2}\right)\Delta y$ del eje $X$, al rotar cada rectángulo se genera un cascarón cilíndrico horizontal de radio medio $y_i^*$, espesor $\Delta y$ y altura/longitud $h_i$, cuyo volumen elemental es $\Delta V_i = 2\pi y_i^* g(y_i^*) \Delta y$. La suma de Riemann convergente es:
$$V_N = \sum_{i=1}^{N} 2\pi \, y_i^* \, g(y_i^*) \, \Delta y \xrightarrow[N \to \infty]{} V$$
\end{definicion}

