      ctx.moveTo(ptZ.px, ptZ.py);
      ctx.lineTo(ptTick.px, ptTick.py);
      ctx.stroke();
      ctx.font = '10px sans-serif';
      ctx.fillStyle = '#334155';
      ctx.fillText(zVal.toString(), ptTick.px + 4, ptTick.py + 3);
      ctx.restore();
    }
  }
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    drawGrid3D();
    drawAxes3D();
    // 1. Dibujar la Superficie del Plano \Pi
    drawPlaneSurface();
    // 2. Punto Posición P y Vector p (Origen -> P)
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, P0, '#0284c7', 2.0);
    drawPoint3D(P0, '#0284c7', 5);
    // 3. Vectores Directores u y v aplicados en P
    const U_end = { x: P0.x + U.x, y: P0.y + U.y, z: P0.z + U.z };
    const V_end = { x: P0.x + V.x, y: P0.y + V.y, z: P0.z + V.z };
    drawVector3D(P0, U_end, '#059669', 2.5);
    drawVector3D(P0, V_end, '#d97706', 2.5);
    // 4. Vector Normal n = u x v (Perpendicular al plano \Pi)
    const N_end = { x: P0.x + N.x, y: P0.y + N.y, z: P0.z + N.z };
    drawVector3D(P0, N_end, '#e11d48', 3.0);
    // 5. Punto Generado x(s, t) = p + s*u + t*v
    const X_curr = {
      x: P0.x + paramS * U.x + paramT * V.x,
      y: P0.y + paramS * U.y + paramT * V.y,
      z: P0.z + paramS * U.z + paramT * V.z
    };
    // Vector Desplazamiento (x - p) contenido en el plano
    drawLine3D(P0, X_curr, '#8b5cf6', 2.2);
    drawPoint3D(X_curr, '#8b5cf6', 6);
    // Indicador de Ángulo Recto 90º entre el Vector Normal n y el Desplazamiento (x - p)
    const lenDisp = Math.hypot(X_curr.x - P0.x, X_curr.y - P0.y, X_curr.z - P0.z);
    const lenN = Math.hypot(N.x, N.y, N.z);
    if (lenDisp > 0.3) {
      const uDisp = { x: (X_curr.x - P0.x) / lenDisp, y: (X_curr.y - P0.y) / lenDisp, z: (X_curr.z - P0.z) / lenDisp };
      const uN = { x: N.x / lenN, y: N.y / lenN, z: N.z / lenN };
      const sSize = 0.35;
      const c1 = { x: P0.x + sSize * uDisp.x, y: P0.y + sSize * uDisp.y, z: P0.z + sSize * uDisp.z };
      const c2 = { x: P0.x + sSize * uDisp.x + sSize * uN.x, y: P0.y + sSize * uDisp.y + sSize * uN.y, z: P0.z + sSize * uDisp.z + sSize * uN.z };
      const c3 = { x: P0.x + sSize * uN.x, y: P0.y + sSize * uN.y, z: P0.z + sSize * uN.z };
      const pC1 = project3D(c1.x, c1.y, c1.z);
      const pC2 = project3D(c2.x, c2.y, c2.z);
      const pC3 = project3D(c3.x, c3.y, c3.z);
      ctx.save();
      ctx.beginPath();
      ctx.strokeStyle = '#e11d48';
      ctx.lineWidth = 1.8;
      ctx.moveTo(pC1.px, pC1.py);
      ctx.lineTo(pC2.px, pC2.py);
      ctx.lineTo(pC3.px, pC3.py);
      ctx.stroke();
      ctx.restore();
    }
    // Actualizar Posición de Etiquetas KaTeX Flotantes
    const posP0 = project3D(P0.x, P0.y, P0.z);
    const posU  = project3D(P0.x + U.x * 0.5, P0.y + U.y * 0.5, P0.z + U.z * 0.5);
    const posV  = project3D(P0.x + V.x * 0.5, P0.y + V.y * 0.5, P0.z + V.z * 0.5);
    const posN  = project3D(N_end.x, N_end.y, N_end.z);
    const posX  = project3D(X_curr.x, X_curr.y, X_curr.z);
    const posPi = project3D(P0.x + 1.2 * U.x + 1.2 * V.x, P0.y + 1.2 * U.y + 1.2 * V.y, P0.z + 1.2 * U.z + 1.2 * V.z);
    if (lblP)  { lblP.style.left  = posP0.px + 'px'; lblP.style.top  = (posP0.py - 12) + 'px'; }
    if (lblU)  { lblU.style.left  = posU.px + 'px';  lblU.style.top  = (posU.py - 12) + 'px'; }
    if (lblV)  { lblV.style.left  = posV.px + 'px';  lblV.style.top  = (posV.py - 12) + 'px'; }
    if (lblN)  { lblN.style.left  = posN.px + 'px';  lblN.style.top  = (posN.py - 14) + 'px'; }
    if (lblX)  { lblX.style.left  = posX.px + 'px';  lblX.style.top  = (posX.py - 14) + 'px'; }
    if (lblPi) { lblPi.style.left = posPi.px + 'px'; lblPi.style.top = (posPi.py - 10) + 'px'; }
    // Actualizar Panel de Información Overlay KaTeX
    if (infoOverlay) {
      infoOverlay.innerHTML = `
        <div style="color: #0284c7; font-weight: 700; margin-bottom: 2px;">Ecuaciones del Plano \\(\\Pi\\)</div>
        <div style="color: #334155; font-size: 12px;">Punto de anclaje: \\(\\vec{p} = (1.00, 1.00, 1.00)\\)</div>
        <div style="color: #059669; font-size: 12px; margin-top: 3px;"><b>1. Paramétrica:</b> \\(\\vec{x} = \\vec{p} + s\\vec{u} + t\\vec{v}\\)</div>
        <div style="color: #334155; font-size: 11px; margin-left: 10px;">Para \\(s = ${paramS.toFixed(2)}, t = ${paramT.toFixed(2)}\\): \\(\\vec{x} = (${X_curr.x.toFixed(2)}, ${X_curr.y.toFixed(2)}, ${X_curr.z.toFixed(2)})\\)</div>
        <div style="color: #e11d48; font-size: 12px; margin-top: 4px;"><b>2. Cartesiana (Normal):</b> \\(\\vec{n} \\cdot (\\vec{x} - \\vec{p}) = 0\\)</div>
        <div style="color: #334155; font-size: 11px; margin-left: 10px;">Ecuación: \\(x + y - 2z = 0\\)</div>
      `;
      if (window.renderMathInElement) {
        window.renderMathInElement(infoOverlay, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }
  // Sliders s y t
  sliderS.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    paramS = parseFloat(e.target.value);
    valS.textContent = paramS.toFixed(2);
    draw();
  });
  sliderT.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    paramT = parseFloat(e.target.value);
    valT.textContent = paramT.toFixed(2);
    draw();
  });
  // Animación suave de exploración del plano
  function animatePlaneExploration() {
    if (isAnimating) {
      stopAnimation();
      return;
    }
    isAnimating = true;
    btnAnim.innerHTML = '⏸ Pausar';
    function stepAnim() {
      if (!isAnimating) return;
      animAngle += 0.025;
      paramS = 0.8 * Math.cos(animAngle);
      paramT = 0.8 * Math.sin(animAngle);
      sliderS.value = paramS;
      sliderT.value = paramT;
      valS.textContent = paramS.toFixed(2);
      valT.textContent = paramT.toFixed(2);
      draw();
      animId = requestAnimationFrame(stepAnim);
    }
    stepAnim();
  }
  function stopAnimation() {
    isAnimating = false;
    if (animId) cancelAnimationFrame(animId);
    btnAnim.innerHTML = '▶ Explorar Plano (s, t)';
  }
  btnAnim.onclick = animatePlaneExploration;
  document.getElementById('btnResetParams_plano').onclick = () => {
    if (isAnimating) stopAnimation();
    paramS = 0.5; paramT = 0.5;
    sliderS.value = 0.5; sliderT.value = 0.5;
    valS.textContent = '0.50'; valT.textContent = '0.50';
    draw();
  };
  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });
  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
