  const container = document.getElementById('containerAnguloRectaPlano3D');
  const wrapper = document.getElementById('wrapperAnguloRectaPlano3D');
  const canvas = document.getElementById('canvasAnguloRectaPlano3D');
  const ctx = canvas.getContext('2d');
  const sliderTheta = document.getElementById('sliderThetaDeg');
  const valTheta = document.getElementById('valThetaDeg');
  const infoOverlay = document.getElementById('infoAngulo3D');
  const btnAnim = document.getElementById('btnAnimAngulo');

  // Etiquetas KaTeX flotantes
  const lblP = document.getElementById('labelP_ang');
  const lblD = document.getElementById('labelD_ang');
  const lblN = document.getElementById('labelN_ang');
  const lblL = document.getElementById('labelL_ang');
  const lblPi = document.getElementById('labelPi_ang');
  const lblTheta = document.getElementById('labelTheta_ang');
  const lblTilde = document.getElementById('labelTilde_ang');

  // Geometría
  const P0 = { x: 1.0, y: 1.0, z: 1.0 }; // Punto de anclaje p
  const N  = { x: 0.0, y: 0.0, z: 2.5 }; // Vector normal n (perpendicular a plano z=1)

  let thetaDeg = parseFloat(sliderTheta.value); // Ángulo en grados [0, 90]
  let isAnimating = false;
  let animId = null;
  let animDirection = 1;

  // Cámara (Estándar 1 Oficial)
  let yaw = -0.65;
  let pitch = 0.45;
  let zoom = 1.0;
  let panX = 0;
  let panY = 0;

  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };

  // Proyección 3D a 2D
  function project3D(x, y, z) {
    const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
    const x1 = x * cosY - y * sinY;
    const y1 = x * sinY + y * cosY;
    const z1 = z;

    const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
    const x2 = x1;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;

    const currentScale = 35 * zoom;
    const cx = canvas.width / 2 + panX;
    const cy = canvas.height / 2 + panY;

    return {
      px: cx + x2 * currentScale,
      py: cy - z2 * currentScale,
      zDepth: y2
    };
  }

  function drawLine3D(pA, pB, color, width = 1.5, dash = []) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    ctx.save();
    ctx.beginPath();
    ctx.setLineDash(dash);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();
    ctx.restore();
  }

  function drawVector3D(pA, pB, color, width = 2) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    const dx = b.px - a.px;
    const dy = b.py - a.py;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) return;

    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();

    const angle = Math.atan2(dy, dx);
    const headLen = 9;
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.moveTo(b.px, b.py);
    ctx.lineTo(b.px - headLen * Math.cos(angle - Math.PI / 6), b.py - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(b.px - headLen * Math.cos(angle + Math.PI / 6), b.py - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawPoint3D(pt, color, radius = 4) {
    const p = project3D(pt.x, pt.y, pt.z);
    ctx.save();
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.arc(p.px, p.py, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.restore();
  }

  // Dibujar arco de ángulo en 3D entre dos vectores v1 y v2 saliendo de P0
  function drawAngleArc3D(P, v1, v2, radius, color, width = 2) {
    const len1 = Math.hypot(v1.x, v1.y, v1.z);
    const len2 = Math.hypot(v2.x, v2.y, v2.z);
    if (len1 < 1e-4 || len2 < 1e-4) return;

    const u1 = { x: v1.x / len1, y: v1.y / len1, z: v1.z / len1 };
    const u2 = { x: v2.x / len2, y: v2.y / len2, z: v2.z / len2 };

    const steps = 16;
    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;

    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const vx = (1 - t) * u1.x + t * u2.x;
      const vy = (1 - t) * u1.y + t * u2.y;
      const vz = (1 - t) * u1.z + t * u2.z;
      const vLen = Math.hypot(vx, vy, vz);
      if (vLen < 1e-4) continue;

      const pArc = {
        x: P.x + (vx / vLen) * radius,
        y: P.y + (vy / vLen) * radius,
        z: P.z + (vz / vLen) * radius
      };
      const p2D = project3D(pArc.x, pArc.y, pArc.z);

      if (i === 0) ctx.moveTo(p2D.px, p2D.py);
      else ctx.lineTo(p2D.px, p2D.py);
    }
    ctx.stroke();
    ctx.restore();
  }

  // Dibujar Plano Sombreado en z = 1
  function drawPlaneSurface() {
    const corners = [
      { x: -1.0, y: -1.0, z: 1.0 },
      { x:  4.5, y: -1.0, z: 1.0 },
      { x:  4.5, y:  4.5, z: 1.0 },
      { x: -1.0, y:  4.5, z: 1.0 }
    ];
    const pts2D = corners.map(pt => project3D(pt.x, pt.y, pt.z));

    ctx.save();
    ctx.beginPath();
    ctx.moveTo(pts2D[0].px, pts2D[0].py);
    ctx.lineTo(pts2D[1].px, pts2D[1].py);
    ctx.lineTo(pts2D[2].px, pts2D[2].py);
    ctx.lineTo(pts2D[3].px, pts2D[3].py);
    ctx.closePath();

    ctx.fillStyle = 'rgba(56, 189, 248, 0.15)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(2, 132, 199, 0.4)';
    ctx.lineWidth = 1.2;
    ctx.stroke();

    // Grid del plano z=1
    ctx.strokeStyle = 'rgba(2, 132, 199, 0.2)';
    ctx.lineWidth = 0.8;
    for (let x = 0; x <= 4; x++) {
      const pA = project3D(x, -1, 1), pB = project3D(x, 4.5, 1);
      ctx.beginPath(); ctx.moveTo(pA.px, pA.py); ctx.lineTo(pB.px, pB.py); ctx.stroke();
    }
    for (let y = 0; y <= 4; y++) {
      const pA = project3D(-1, y, 1), pB = project3D(4.5, y, 1);
      ctx.beginPath(); ctx.moveTo(pA.px, pA.py); ctx.lineTo(pB.px, pB.py); ctx.stroke();
    }
    ctx.restore();
  }

  function drawGrid3D() {
    ctx.beginPath();
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = -1; i <= 5; i++) {
      const pA1 = project3D(i, -1, 0), pA2 = project3D(i, 5, 0);
      ctx.moveTo(pA1.px, pA1.py); ctx.lineTo(pA2.px, pA2.py);

      const pB1 = project3D(-1, i, 0), pB2 = project3D(5, i, 0);
      ctx.moveTo(pB1.px, pB1.py); ctx.lineTo(pB2.px, pB2.py);
    }
    ctx.stroke();
  }

  function drawAxes3D() {
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, { x: 5.2, y: 0, z: 0 }, '#000000', 2.0); // Eje X
    drawVector3D(O, { x: 0, y: 5.2, z: 0 }, '#000000', 2.0); // Eje Y
    drawVector3D(O, { x: 0, y: 0, z: 5.2 }, '#000000', 2.0); // Eje Z

    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#000000';
    const px = project3D(5.5, 0, 0);
    const py = project3D(0, 5.5, 0);
    const pz = project3D(0, 0, 5.5);

    ctx.fillText('x', px.px, px.py);
    ctx.fillText('y', py.px, py.py);
    ctx.fillText('z', pz.px, pz.py);

    // Graduación Eje Z
    //for (let zVal = 1; zVal <= 5; zVal++) {
      //const ptZ = project3D(0, 0, zVal);
      //const ptTick = project3D(0.12, 0, zVal);

      //ctx.save();
      //ctx.beginPath();
      //ctx.strokeStyle = '#000000';
      //ctx.lineWidth = 1.2;
      //ctx.moveTo(ptZ.px, ptZ.py);
      //ctx.lineTo(ptTick.px, ptTick.py);
      //ctx.stroke();

      //ctx.font = '10px sans-serif';
      //ctx.fillStyle = '#334155';
      //ctx.fillText(zVal.toString(), ptTick.px + 4, ptTick.py + 3);
      //ctx.restore();
    //}
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawGrid3D();
    drawAxes3D();

    // 1. Dibujar Plano Pi
    drawPlaneSurface();

    // 2. Punto P y Vector Normal n en P
    drawPoint3D(P0, '#0284c7', 5);
    const N_end = { x: P0.x + N.x, y: P0.y + N.y, z: P0.z + N.z };
    drawVector3D(P0, N_end, '#e11d48', 2.8);

    // Símbolo de 90° entre Normal n y el Plano
    const sSize = 0.35;
    const c1 = { x: P0.x + sSize, y: P0.y, z: P0.z };
    const c2 = { x: P0.x + sSize, y: P0.y, z: P0.z + sSize };
    const c3 = { x: P0.x, y: P0.y, z: P0.z + sSize };
    const pC1 = project3D(c1.x, c1.y, c1.z);
    const pC2 = project3D(c2.x, c2.y, c2.z);
    const pC3 = project3D(c3.x, c3.y, c3.z);

    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = '#e11d48';
    ctx.lineWidth = 1.4;
    ctx.moveTo(pC1.px, pC1.py); ctx.lineTo(pC2.px, pC2.py); ctx.lineTo(pC3.px, pC3.py);
    ctx.stroke();
    ctx.restore();

    // 3. Vector Director d(theta) y Proyección d_Pi sobre el plano
    const radTheta = (thetaDeg * Math.PI) / 180;
    const lenD = 2.5;

    const D_vec = {
      x: lenD * Math.cos(radTheta),
      y: 0,
      z: lenD * Math.sin(radTheta)
    };

    const D_proj = {
      x: lenD * Math.cos(radTheta),
      y: 0,
      z: 0
    };

    const D_end = { x: P0.x + D_vec.x, y: P0.y + D_vec.y, z: P0.z + D_vec.z };
    const D_proj_end = { x: P0.x + D_proj.x, y: P0.y + D_proj.y, z: P0.z + D_proj.z };

    // Dibujar Recta L pasando por P0 con dirección d
    const L_start = { x: P0.x - 1.2 * D_vec.x, y: P0.y, z: P0.z - 1.2 * D_vec.z };
    const L_end   = { x: P0.x + 1.5 * D_vec.x, y: P0.y, z: P0.z + 1.5 * D_vec.z };
    drawLine3D(L_start, L_end, '#0284c7', 2.0, [5, 4]);

    // Dibujar Vector Director d (Azul Cyan)
    drawVector3D(P0, D_end, '#0284c7', 2.8);

    // Dibujar Proyección d_Pi (Verde)
    drawVector3D(P0, D_proj_end, '#059669', 2.2);

    // Línea punteada de proyección vertical entre d_end y d_proj_end
    drawLine3D(D_end, D_proj_end, '#94a3b8', 1.5, [3, 3]);

    // 4. Arcos de Ángulo en 3D
    if (thetaDeg > 3 && thetaDeg < 87) {
      drawAngleArc3D(P0, D_proj, D_vec, 0.8, '#059669', 2.2);
      drawAngleArc3D(P0, D_vec, N, 0.9, '#e11d48', 2.2);
    }

    // 5. Cálculos Matemáticos de los Ángulos
    const tildeDeg = 90 - thetaDeg;
    const sinTheta = Math.sin(radTheta);
    const cosTilde = Math.cos((tildeDeg * Math.PI) / 180);

    // Posición de Etiquetas KaTeX Flotantes
    const posP0 = project3D(P0.x, P0.y, P0.z);
    const posD  = project3D(P0.x + D_vec.x * 0.6, P0.y, P0.z + D_vec.z * 0.6);
    const posN  = project3D(N_end.x, N_end.y, N_end.z);
    const posL  = project3D(L_end.x, L_end.y, L_end.z);
    const posPi = project3D(3.5, 3.5, 1.0);

    const posThetaMid = project3D(
      P0.x + 1.1 * Math.cos(radTheta * 0.5),
      P0.y,
      P0.z + 1.1 * Math.sin(radTheta * 0.5)
    );

    const radMidTilde = radTheta + ((Math.PI / 2 - radTheta) * 0.5);
    const posTildeMid = project3D(
      P0.x + 1.2 * Math.cos(radMidTilde),
      P0.y,
      P0.z + 1.2 * Math.sin(radMidTilde)
    );

    if (lblP) { lblP.style.left = posP0.px + 'px'; lblP.style.top = (posP0.py - 12) + 'px'; }
    if (lblD) { lblD.style.left = posD.px + 'px';  lblD.style.top  = (posD.py - 14) + 'px'; }
    if (lblN) { lblN.style.left = posN.px + 'px';  lblN.style.top  = (posN.py - 14) + 'px'; }
    if (lblL) { lblL.style.left = posL.px + 'px';  lblL.style.top  = (posL.py - 10) + 'px'; }
    if (lblPi){ lblPi.style.left = posPi.px + 'px'; lblPi.style.top = (posPi.py - 10) + 'px'; }

    if (lblTheta) {
      lblTheta.style.left = posThetaMid.px + 'px';
      lblTheta.style.top  = (posThetaMid.py - 10) + 'px';
    }

    if (lblTilde) {
      lblTilde.style.left = posTildeMid.px + 'px';
      lblTilde.style.top  = (posTildeMid.py - 10) + 'px';
    }

    // Actualizar Panel Overlay KaTeX Top-Left
    if (infoOverlay) {
      infoOverlay.innerHTML = `
        <div style="color: #0284c7; font-weight: 700; margin-bottom: 3px;">Relación entre Ángulos en \\(\\mathbb{R}^3\\)</div>
        <div style="color: #059669; font-size: 12px;"><b>1. Inclinación Recta-Plano:</b> \\(\\theta = ${thetaDeg.toFixed(1)}^\\circ\\)</div>
        <div style="color: #334155; font-size: 11px; margin-left: 10px;">\\(\\sin(\\theta) = \\frac{|\\vec{n} \\cdot \\vec{d}|}{\\|\\vec{n}\\| \\|\\vec{d}\\|} = ${sinTheta.toFixed(3)}\\)</div>
        <div style="color: #e11d48; font-size: 12px; margin-top: 4px;"><b>2. Incidencia Recta-Normal:</b> \\(\\tilde{\\theta} = ${tildeDeg.toFixed(1)}^\\circ\\)</div>
        <div style="color: #334155; font-size: 11px; margin-left: 10px;">\\(\\cos(\\tilde{\\theta}) = \\frac{|\\vec{n} \\cdot \\vec{d}|}{\\|\\vec{n}\\| \\|\\vec{d}\\|} = ${cosTilde.toFixed(3)}\\)</div>
        <div style="color: #0284c7; font-weight: 600; font-size: 11px; margin-top: 4px; background: #e0f2fe; padding: 3px 6px; border-radius: 4px; display: inline-block;">
          Complementarios: \\(\\theta + \\tilde{\\theta} = 90^\\circ\\) \\(\\implies \\sin(\\theta) = \\cos(\\tilde{\\theta})\\)
        </div>
      `;

      if (window.renderMathInElement) {
        window.renderMathInElement(infoOverlay, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }

  // Slider theta
  sliderTheta.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    thetaDeg = parseFloat(e.target.value);
    valTheta.textContent = thetaDeg.toFixed(1) + '°';
    draw();
  });

  // Animación de oscilación del ángulo theta
  function animateAngleOscillation() {
    if (isAnimating) {
      stopAnimation();
      return;
    }

    isAnimating = true;
    btnAnim.innerHTML = '⏸ Pausar';

    function stepAnim() {
      if (!isAnimating) return;

      thetaDeg += animDirection * 0.6;
      if (thetaDeg >= 85) { thetaDeg = 85; animDirection = -1; }
      if (thetaDeg <= 5)  { thetaDeg = 5;  animDirection = 1; }

      sliderTheta.value = thetaDeg;
      valTheta.textContent = thetaDeg.toFixed(1) + '°';

      draw();
      animId = requestAnimationFrame(stepAnim);
    }

    stepAnim();
  }

  function stopAnimation() {
    isAnimating = false;
    if (animId) cancelAnimationFrame(animId);
    btnAnim.innerHTML = '▶ Animación de Inclinación';
  }

  btnAnim.onclick = animateAngleOscillation;

  document.getElementById('btnResetAngle_ang').onclick = () => {
    if (isAnimating) stopAnimation();
    thetaDeg = 35.0;
    sliderTheta.value = 35.0;
    valTheta.textContent = '35.0°';
    draw();
  };

  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - prevMousePos.x;
    const deltaY = e.clientY - prevMousePos.y;

    yaw += deltaX * 0.008;
    pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));

    prevMousePos = { x: e.clientX, y: e.clientY };
    draw();
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });

  // Zoom con la Rueda
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const oldZoom = zoom;
    let newZoom = oldZoom;

    if (e.deltaY < 0) newZoom = Math.min(3.5, oldZoom * 1.08);
    else newZoom = Math.max(0.3, oldZoom / 1.08);

    if (e.shiftKey) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const scaleRatio = newZoom / oldZoom;
      const originX = (canvas.width / 2) + panX;
      const originY = (canvas.height / 2) + panY;

      panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
      panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2);
    }

    zoom = newZoom;
    draw();
  }, { passive: false });

  // Traslación con Flechas Teclado
  window.addEventListener('keydown', (e) => {
    if (document.activeElement === sliderTheta) return;
    const step = 15;
    if (e.key === 'ArrowLeft') { panX -= step; draw(); }
    else if (e.key === 'ArrowRight') { panX += step; draw(); }
    else if (e.key === 'ArrowUp') { panY -= step; draw(); }
    else if (e.key === 'ArrowDown') { panY += step; draw(); }
  });

  // Botones de Vistas Ortogonales
  document.getElementById('btnVX_ang').onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
  document.getElementById('btnVY_ang').onclick = () => { yaw = 0; pitch = 0; draw(); };
  document.getElementById('btnVZ_ang').onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };
  document.getElementById('btnReset_ang').onclick = () => {
    yaw = -0.65; pitch = 0.45; zoom = 1.0; panX = 0; panY = 0; draw();
  };

  // Pantalla Completa Adaptativa 100%
  document.getElementById('btnFS_ang').onclick = () => {
    if (!document.fullscreenElement) {
      if (container.requestFullscreen) container.requestFullscreen();
      else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
    } else {
      if (document.exitFullscreen) document.exitFullscreen();
    }
  };

  function updateCanvasSize() {
    if (document.fullscreenElement) {
      container.style.width = '100vw';
      container.style.height = '100vh';
      container.style.borderRadius = '0';
      container.style.padding = '16px';
      container.style.display = 'flex';
      container.style.flexDirection = 'column';
      container.style.justifyContent = 'space-between';

      const controlsHeight = 130;
      wrapper.style.width = '100%';
      wrapper.style.height = `${window.innerHeight - controlsHeight}px`;

      canvas.width = wrapper.clientWidth;
      canvas.height = window.innerHeight - controlsHeight;
    } else {
      container.style.width = '';
      container.style.height = '';
      container.style.borderRadius = '16px';
      container.style.padding = '16px';
      container.style.display = 'inline-block';

      wrapper.style.width = '620px';
      wrapper.style.height = '400px';

      canvas.width = 620;
      canvas.height = 400;
    }
    draw();
  }

  document.addEventListener('fullscreenchange', updateCanvasSize);
  window.addEventListener('resize', updateCanvasSize);

  draw();
})();
</script>
\end{html}
