\begin{card}
<p>\textbf{Proyección ortogonal de un punto sobre una recta}</p>

La proyección ortogonal representa la "sombra" matemática que proyecta un objeto sobre una superficie plana bajo una iluminación perpendicular.

\begin{definicion}{Proyección ortogonal de un punto sobre un plano}

Dado un punto en el espacio con vector posición $\vec{q}$ y un plano $\Pi: ax + by + cz + d = 0$ con vector normal $\vec{n} = (a, b, c)$, la \textbf{proyección ortogonal} de $\vec{q}$ sobre $\Pi$ es el único punto $\operatorname{proy}_\Pi(\vec{q})\in \Pi$ tal que el vector diferencia $\vec{q} - \operatorname{proy}_\Pi(\vec{q})$ es paralelo al vector normal $\vec{n}$.
\end{definicion}




\begin{metodo}{Cálculo de $\operatorname{proy}_\Pi(\vec{q})$}

\problema{Dado el punto $\vec{q} = (1, 2, 5)$ y el plano $\Pi: 2x - y + 2z - 3 = 0$ determinar $\operatorname{proy}_\Pi(\vec{q})$}

\paso{1}{Construir la recta perpendicular al plano que pasa por $\vec{q}$}
Formar una recta auxiliar $L_{\perp}$ que pase por $\vec{q}$ usando el vector normal del plano $\vec{n} = (a, b, c)$ como vector director:
$$L_{\perp}: \vec{x} = \vec{q} + \lambda\vec{n}$$

\begin{ejemplo}
Con $\vec{q} = (1, 2, 5)$ y $\vec{n} = (2, -1, 2)$:
$$L_{\perp}: \vec{x} = \begin{pmatrix} 1 \\ 2 \\ 5 \end{pmatrix} + \lambda \begin{pmatrix} 2 \\ -1 \\ 2 \end{pmatrix}$$
En ecuaciones paramétricas: $x = 1 + 2\lambda$, $y = 2 - \lambda$, $z = 5 + 2\lambda$.
\end{ejemplo}

\paso{2}{Hallar la intersección entre $L_{\perp}$ y el plano $\Pi$}
Sustituir las expresiones paramétricas de $L_{\perp}$ en la ecuación del plano $\Pi$ para encontrar el parámetro $\lambda_0$.

\begin{ejemplo}
$$2(1 + 2\lambda) - (2 - \lambda) + 2(5 + 2\lambda) - 3 = 0$$
$$2 + 4\lambda - 2 + \lambda + 10 + 4\lambda - 3 = 0 \iff 9\lambda + 7 = 0 \implies \lambda_0 = -\frac{7}{9}$$
\end{ejemplo}

\paso{3}{Evaluar $\lambda_0$ para obtener el vector posición de$\operatorname{proy}_\Pi(\vec{q})$}
Sustituir el parámetro $\lambda_0$ en la recta $L_{\perp}$ para hallar el vector posición $\operatorname{proy}_\Pi(\vec{q}) = \vec{q} + \lambda_0\vec{n}$.

\begin{ejemplo}
$$\operatorname{proy}_\Pi(\vec{q}) = \begin{pmatrix} 1 \\ 2 \\ 5 \end{pmatrix} - \frac{7}{9}\begin{pmatrix} 2 \\ -1 \\ 2 \end{pmatrix} = \begin{pmatrix} 1 - 14/9 \\ 2 + 7/9 \\ 5 - 14/9 \end{pmatrix} = \begin{pmatrix} -5/9 \\ 25/9 \\ 31/9 \end{pmatrix}$$
El vector posición del pie de la perpendicular es $\operatorname{proy}_\Pi(\vec{q})= \left(-\frac{5}{9}, \frac{25}{9}, \frac{31}{9}\right)$.
\end{ejemplo}

\end{metodo}

\begin{teorema}{Propiedad de Mínima Distancia del Pie de la Perpendicular}

El punto con vector posición $\operatorname{proy}_\Pi(\vec{q})$ es el único punto perteneciente al plano $\Pi$ que se encuentra a la menor distancia absoluta del vector posición $\vec{q}$.
Para cualquier otro punto $\vec{x} \in \Pi$ con $\vec{x} \neq \operatorname{proy}_\Pi(\vec{q})$, se cumple que:
$$\|\vec{q} - \operatorname{proy}_\Pi(\vec{q})\| < \|\vec{q} - \vec{x}\|$$


\demostracion{

Denotemos por $\vec{q}_H = \operatorname{proy}_\Pi(\vec{q})$ a la proyección ortogonal de $\vec q$ sobre $\Pi$.

1. Por definición de proyección ortogonal, el vector desplazamiento $(\vec{q} - \vec{q}_H)$ es perpendicular al plano $\Pi$, lo que significa que es ortogonal a cualquier vector contenido dentro del plano.

2. Sea $\vec{x} \in \Pi$ un punto arbitrario del plano distinto de $\vec{q}_H$ ($\vec{x} \neq \vec{q}_H$). Como tanto $\vec{q}_H$ como $\vec{x}$ pertenecen a $\Pi$, el vector diferencia $(\vec{q}_H - \vec{x})$ está completamente contenido en el plano.

3. Debido a la ortogonalidad entre la normal al plano y cualquier vector del plano, tenemos:
$$(\vec{q} - \vec{q}_H) \cdot (\vec{q}_H - \vec{x}) = 0$$
4. Descomponemos el vector distancia entre $\vec{q}$ y $\vec{x}$ sumando y restando $\vec{q}_H$:
$$\vec{q} - \vec{x} = (\vec{q} - \vec{q}_H) + (\vec{q}_H - \vec{x})$$
5. Calculamos la norma al cuadrado de ambos lados y aplicamos el \textbf{Teorema de Pitágoras} gracias a la ortogonalidad demostrada en el paso 3:
$$\|\vec{q} - \vec{x}\|^2 = \|(\vec{q} - \vec{q}_H) + (\vec{q}_H - \vec{x})\|^2 = \|\vec{q} - \vec{q}_H\|^2 + \|\vec{q}_H - \vec{x}\|^2$$
6. Dado que $\vec{x} \neq \vec{q}_H$, la distancia $\| \vec{q}_H - \vec{x} \|$ es estrictamente positiva ($\| \vec{q}_H - \vec{x} \|^2 > 0$). Por lo tanto:
$$\begin{align*}\|\vec{q} - \vec{x}\|^2 &= \|\vec{q} - \vec{q}_H\|^2 + \|\vec{q}_H - \vec{x}\|^2\\\|\vec{q} - \vec{x}\|^2 &> \|\vec{q} - \vec{q}_H\|^2\end{align*}$$
Extrayendo raíz cuadrada a ambos lados, concluimos la desigualdad estricta:
$$\|\vec{q} - \operatorname{proy}_\Pi(\vec{q})\| < \|\vec{q} - \vec{x}\|$$
}
\end{teorema}

\begin{teorema}{Distancia de un Punto a un Plano}

Dado un punto en el espacio con vector posición $\vec{q} = (x_0, y_0, z_0)$ y un plano $\Pi: ax + by + cz + d = 0$ con vector normal $\vec{n} = (a, b, c) \neq \vec{0}$, la distancia mínima perpendicular $d(\vec{q}, \Pi)$ viene dada por:

$$d(\vec{q}, \Pi) =\|\vec q-\operatorname{proy}_\Pi(\vec q)\|=\frac{|\vec{n} \cdot \vec{q} + d|}{\|\vec{n}\|}=\frac{|a x_0 + b y_0 + c z_0 + d|}{\sqrt{a^2 + b^2 + c^2}}  $$
\end{teorema}
\end{card}

\begin{card}
\begin{teorema}{Proyección Ortogonal de una Recta sobre un Plano}
Dada una recta $L: \vec{x} = \vec{p} + \lambda\vec{d}$ no perpendicular al plano $\Pi$ (es decir $\vec{n} \times \vec{d} \neq \vec{0}$), la proyección ortogonal de $L$ sobre $\Pi$ es una nueva recta $L_{\Pi} \subset \Pi$ dada por:
$$L_\Pi: \vec{x} = \operatorname{proy}_\Pi(\vec{p}) + \lambda\vec{d}_{\text{proj}}$$
donde:
$\vec{p}_H$ es el pie de la perpendicular del punto $\vec{p}$ sobre $\Pi$.
$\bullet$ $\vec{d}_{\text{proj}}$ es el vector director proyectado, dado por la descomposición ortogonal de $\vec{d}$ respecto a $\vec{n}$:
$$\vec{d}_{\text{proj}} = \vec{d} - \text{proj}_{\vec{n}}(\vec{d}) = \vec{d} - \left(\frac{\vec{d} \cdot \vec{n}}{\|\vec{n}\|^2}\right)\vec{n}$$
\end{teorema}

\begin{trampa}{Diferencia entre Pie de la Perpendicular y Punto Simétrico}
\error{Confundir el pie de la perpendicular $\vec{q}_H$ (que es el punto de proyección contenido en el plano $\Pi$) con el punto simétrico $\vec{q}'$ del punto $\vec{q}$ respecto al plano.}
\correct{El pie de la perpendicular $\vec{q}_H$ es el \textbf{punto medio} del segmento que une a $\vec{q}$ con su simétrico $\vec{q}'$. Por lo tanto, una vez calculado $\vec{q}_H$, el vector posición del punto simétrico $\vec{q}'$ se obtiene despejando de la relación del punto medio:
$$\vec{q}_H = \frac{\vec{q} + \vec{q}'}{2} \implies \vec{q}' = 2\vec{q}_H - \vec{q}$$}
\end{trampa}
\end{card}
\begin{card}
\textbf{1. Distancia Mínima de un Punto a un Plano}

En geometría tridimensional, la distancia de un punto a una superficie plana se define como la menor longitud posible entre el punto y cualquier punto del plano, la cual se mide a lo largo de la trayectoria perpendicular.



$\bullet$ \textbf{Deducción Vectorial:} Si elegimos cualquier punto de anclaje $\vec{p}_0 = (x_0, y_0, z_0)$ perteneciente a $\Pi$, la distancia es la magnitud de la proyección ortogonal del vector desplazamiento $(\vec{q} - \vec{p}_0)$ sobre la dirección normal $\vec{n}$:
$$d(\vec{q}, \Pi) = \|\text{proj}_{\vec{n}}(\vec{q} - \vec{p}_0)\| = \frac{|(\vec{q} - \vec{p}_0) \cdot \vec{n}|}{\|\vec{n}\|} = \frac{|\vec{n} \cdot \vec{q} - \vec{n} \cdot \vec{p}_0|}{\|\vec{n}\|}$$
Como $\vec{p}_0 \in \Pi$, se tiene que $\vec{n} \cdot \vec{p}_0 = -d$, con lo cual recuperamos la fórmula exacta.
\end{card}

\begin{card}
\textbf{2. Algoritmo: Distancia entre Planos Paralelos}

\begin{metodo}{Cálculo de la Distancia entre Dos Planos Paralelos}

\problema{Calcular la distancia exacta entre los planos paralelos $\Pi_1: 2x - 3y + 6z - 14 = 0$ y $\Pi_2: 4x - 6y + 12z + 7 = 0$.}

\paso{1}{Igualar los vectores normales de ambos planos}
Ajustar los coeficientes multiplicando o dividiendo una de las ecuaciones para que ambos planos compartan el mismo vector normal $\vec{n} = (a, b, c)$.

\begin{ejemplo}
El plano $\Pi_1$ tiene normal $\vec{n}_1 = (2, -3, 6)$.
Dividiendo la ecuación de $\Pi_2$ por $2$:
$$\Pi_2: \frac{4}{2}x - \frac{6}{2}y + \frac{12}{2}z + \frac{7}{2} = 0 \iff 2x - 3y + 6z + \frac{7}{2} = 0$$
Ahora ambos planos comparten la normal $\vec{n} = (2, -3, 6)$ con términos independientes $d_1 = -14$ y $d_2 = 7/2$.
\end{ejemplo}

\paso{2}{Aplicar la fórmula de distancia entre planos paralelos}
La distancia entre dos planos paralelos con normales idénticas se simplifica a la diferencia de sus constantes independientes:
$$d(\Pi_1, \Pi_2) = \frac{|d_1 - d_2|}{\sqrt{a^2 + b^2 + c^2}}$$

\begin{ejemplo}
$$d(\Pi_1, \Pi_2) = \frac{|-14 - 7/2|}{\sqrt{2^2 + (-3)^2 + 6^2}} = \frac{|-35/2|}{\sqrt{4 + 9 + 36}} = \frac{35/2}{\sqrt{49}} = \frac{35/2}{7} = \frac{5}{2}$$
La separación exacta entre los dos planos paralelos es $5/2$.
\end{ejemplo}

\end{metodo}
\end{card}

\begin{card}
\textbf{3. El Punto donde se Alcanza la Distancia Mínima}

\begin{teorema}
\textbf{Punto de Mínima Distancia en el Plano}

Dado el punto $\vec{q} = (x_0, y_0, z_0)$ y el plano $\Pi: ax + by + cz + d = 0$, el único punto $\vec{p}^* \in \Pi$ que minimiza la distancia es el pie de la perpendicular $\vec{q}_H$, cuya expresión vectorial directa es:

$$\vec{p}^* = \vec{q}_H = \vec{q} - \left(\frac{a x_0 + b y_0 + c z_0 + d}{a^2 + b^2 + c^2}\right)\vec{n}$$
\end{teorema}

\begin{trampa}{Ponderación del Vector Normal no Unitario}
\error{Olvidar dividir por la norma del vector normal $\|\vec{n}\| = \sqrt{a^2 + b^2 + c^2}$ al evaluar la distancia de un punto a un plano, usando erróneamente solo el numerador $|a x_q + b y_q + c z_q + d|$.}
\correct{El término $|a x_q + b y_q + c z_q + d|$ da el valor de la distancia escalada por $\|\vec{n}\|$. La distancia geométrica real exige dividir siempre por la norma del vector normal: $d(\vec{q}, \Pi) = \frac{|a x_q + b y_q + c z_q + d|}{\sqrt{a^2 + b^2 + c^2}}$.}
\end{trampa}
\end{card}

\begin{card}

Un espacio vectorial es una estructura algebraica formada por un conjunto de objetos (llamados \textbf{vectores}) sobre los cuales se definen dos operaciones compatibles: una suma entre vectores y un producto de un número (escalar) por un vector.

\begin{definicion}
{Espacio Vectorial sobre un Cuerpo $\mathbb{K}$}

Sea $V$ un conjunto no vacío y sea $\mathbb{K}$ un cuerpo ($\mathbb{R}$ o $\mathbb{C}$). Consideremos dos operaciones:
<ul class="list-disc pl-5 space-y-2">
  <li><strong>Suma interna</strong> ($+: V \times V \to V$): A cada par de vectores $(\vec{u}, \vec{v}) \in V \times V$ le asigna un único vector $(\vec{u} + \vec{v}) \in V$.</li>
<li><strong>Multiplicación por escalar</strong> ($\cdot: \mathbb{K} \times V \to V$): A cada par $(\alpha, \vec{v}) \in \mathbb{K} \times V$ le asigna un único vector $(\alpha \cdot \vec{v}) \in V$.</li>
</ul>

<p>Diremos que $(V, +, \cdot)$ es un <strong>espacio vectorial sobre</strong> $\mathbb{K}$} si para todo $\vec{u}, \vec{v}, \vec{w} \in V$ y todo $\alpha, \beta \in \mathbb{K}$ se satisfacen los siguientes \textbf{8 axiomas}:</p>

<p>\textbf{Axiomas de la Suma Vectorial:}</p>

<ol class="list-decimal pl-5 space-y-2">
<li>\textbf{Conmutatividad:} $\vec{u} + \vec{v} = \vec{v} + \vec{u}$.</li>
<li>\textbf{Asociatividad:} $\vec{u} + (\vec{v} + \vec{w}) = (\vec{u} + \vec{v}) + \vec{w}$.</li>
<li>\textbf{Neutro Aditivo:} Existe un elemento $\vec{0}_V \in V$ tal que $\vec{v} + \vec{0}_V = \vec{v}$.</li>
<li>\textbf{Inverso Aditivo:} Para cada $\vec{v} \in V$, existe un elemento $-\vec{v} \in V$ tal que $\vec{v} + (-\vec{v}) = \vec{0}_V$.</li>
</ol>

<p>\textbf{Axiomas de la Multiplicación Escalar:}</p>
<ol>
<li>\textbf{Distributividad del escalar:} $\alpha \cdot (\vec{u} + \vec{v}) = \alpha \cdot \vec{u} + \alpha \cdot \vec{v}$.</li>
<li>\textbf{Distributividad del vector:} $(\alpha + \beta) \cdot \vec{v} = \alpha \cdot \vec{v} + \beta \cdot \vec{v}$.</li>
<li>\textbf{Asociatividad escalar:} $\alpha \cdot (\beta \cdot \vec{v}) = (\alpha \beta) \cdot \vec{v}$.</li>
<li>\textbf{Identidad multiplicativa:} $1 \cdot \vec{v} = \vec{v}$ (donde $1$ es el neutro multiplicativo de $\mathbb{K}$).</li>
</ol>
\end{definicion}

\end{card}

\begin{card}

\begin{teorema}{Espacios Vectoriales Canónicos sobre $\mathbb{R}$}
Los siguientes conjuntos, dotados de sus operaciones naturales de suma y multiplicación por escalar real, son espacios vectoriales sobre $\mathbb{R}$:

<ul class="list-disc pl-5 space-y-2">
  <li><strong>Espacio Euclídeo</strong> $n$-dimensional $\mathbb{R}^n$: elementos de la forma $$\vec{x} = (x_1, x_2, \dots, x_n)$$</li>
<li><strong>Espacio de Matrices Rectangulares</strong> $\mathcal{M}_{mn}(\mathbb{R})$: elementos dados por matrices de $m \times n$: $A, B, C \in \mathcal{M}_{mn}(\mathbb{R})$.</li>
<li><strong>Espacio de Polinomios</strong> $\mathcal{P}_n[x](\mathbb{R})$: elementos dados por polinomios de grado menor o igual a $n$:
   $$p(x) = a_0 + a_1 x + a_2 x^2 + \dots + a_n x^n \quad (a_i \in \mathbb{R})$$
<li><strong>Espacio Trivial</strong> $\{\vec{0}_V\}$: Conjunto formado únicamente por el elemento neutro aditivo.</li>
\end{teorema}
<p>\textbf{Aclaración sobre la Notación Generica vs. Notación Concreta:}</p>
La notación utilizada arriba ($\vec{u}, \vec{v}, \vec{w}, \vec{0}_V$) corresponde a la \textbf{notación genérica} para referirnos a un espacio vectorial abstracto.


<ul class="list-disc pl-5 space-y-2">
  <li><strong>Matrices:</strong> Los "vectores" se denotan por $A$, $B$, $C$, etc. .</li>
  <li><strong>Espacio: </strong> $\mathbb{R}^n$: Los vectores se denotan por $\vec{x}$, $\vec y$, $\vec u$, $\vec v$, etc. </li>
  <li><strong>Polinomios:</strong> Los "vectores" se denotan por $p(x)$, $q(x)$, $r(x)$, etc. </li>
  <li><strong>Funciones:</strong> Los "vectores" se denotan por $f(x)$, $g(x)$, $h(x)$, etc. </li>
</ul>
Asimismo, denotaremos al vector nulo  por $\vec{0}_V$ únicamente cuando sea necesario evitar confusiones con el cero escalar $0 \in \mathbb{K}$. 
De igual forma, nos referiremos al espacio vectorial simplemente como $V$ (en lugar de la terna $(V, +, \cdot)$) siempre que sus operaciones de suma y ponderación por escalar sean las usuales.

\end{card}

\begin{card}

A partir de los 8 axiomas fundamentales de espacio vectorial se deducen propiedades algebraicas universales que se cumplen en absolutamente todo espacio vectorial $V$, sin importar si sus elementos son vectores de $\mathbb{R}^n$, matrices o funciones.

\begin{teorema}{Unicidad del Neutro e Inverso Aditivo}

Sea $V$ un espacio vectorial sobre un cuerpo $\mathbb{K}$.

<ul class="list-disc pl-5 space-y-2">
  <li><strong>Unicidad del Neutro Aditivo:</strong> El elemento neutro aditivo $\vec{0}_V \in V$ es único.</li>
  <li><strong>Unicidad del Inverso Aditivo:</strong> Para cada vector $\vec{v} \in V$, su inverso aditivo $-\vec{v} \in V$ es único.</li>
</ul>


\demostracion{


\textbf{1. Unicidad de} $\vec{0}_V$: Supongamos que existen dos neutros aditivos $\vec{0}_1, \vec{0}_2 \in V$.
   - Como $\vec{0}_2$ es neutro aditivo: $\vec{0}_1 + \vec{0}_2 = \vec{0}_1$.
   - Como $\vec{0}_1$ es neutro aditivo y la suma es conmutativa: $\vec{0}_1 + \vec{0}_2 = \vec{0}_2$.
   - Igualando ambas expresiones obtenemos $\vec{0}_1 = \vec{0}_2$. Por lo tanto, el neutro es único.

\textbf{2. Unicidad de} $-\vec{v}$: Dado $\vec{v} \in V$, supongamos que existen dos inversos aditivos $\vec{w}_1, \vec{w}_2 \in V$, tales que $\vec{v} + \vec{w}_1 = \vec{0}_V$ y $\vec{v} + \vec{w}_2 = \vec{0}_V$.
   - Evaluamos $\vec{w}_1$:
     $$\vec{w}_1 = \vec{w}_1 + \vec{0}_V = \vec{w}_1 + (\vec{v} + \vec{w}_2) = (\vec{w}_1 + \vec{v}) + \vec{w}_2 = \vec{0}_V + \vec{w}_2 = \vec{w}_2$$
   - Por lo tanto, $\vec{w}_1 = \vec{w}_2$, lo que demuestra que el inverso aditivo es único.
}
\end{teorema}
\end{card}

\begin{card}

\begin{propiedades}{Propiedades Fundamentales de los Espacios Vectoriales}

\propiedad{Multiplicación por el Cero Escalar}{Para todo vector $\vec{v} \in V$, se cumple que $0 \cdot \vec{v} = \vec{0}_V$.}
\demostracionPropiedad{Multiplicación por el Cero Escalar}{
Usando la propiedad del escalar $0 = 0 + 0$ y la distributividad del vector:
$$0 \cdot \vec{v} = (0 + 0) \cdot \vec{v} = 0 \cdot \vec{v} + 0 \cdot \vec{v}$$
Sumando el inverso aditivo $-(0 \cdot \vec{v})$ a ambos lados de la igualdad:
$$(0 \cdot \vec{v}) + (-(0 \cdot \vec{v})) = (0 \cdot \vec{v} + 0 \cdot \vec{v}) + (-(0 \cdot \vec{v}))$$
$$\vec{0}_V = 0 \cdot \vec{v} + (0 \cdot \vec{v} + (-(0 \cdot \vec{v}))) \implies \vec{0}_V = 0 \cdot \vec{v} + \vec{0}_V \implies 0 \cdot \vec{v} = \vec{0}_V \quad \blacksquare$$
}

\propiedad{Multiplicación de un Escalar por el Vector Nulo}{Para todo escalar $\alpha \in \mathbb{K}$, se cumple que $\alpha \cdot \vec{0}_V = \vec{0}_V$.}
\demostracionPropiedad{Multiplicación de un Escalar por el Vector Nulo}{
Usando la propiedad del neutro $\vec{0}_V = \vec{0}_V + \vec{0}_V$ y la distributividad del escalar:
$$\alpha \cdot \vec{0}_V = \alpha \cdot (\vec{0}_V + \vec{0}_V) = \alpha \cdot \vec{0}_V + \alpha \cdot \vec{0}_V$$
Sumando $-(\alpha \cdot \vec{0}_V)$ a ambos lados de la ecuación, concluimos que $\alpha \cdot \vec{0}_V = \vec{0}_V \quad \blacksquare$.
}

\propiedad{Inverso Aditivo mediante el Escalar $-1$}{Para todo vector $\vec{v} \in V$, se cumple que $(-1) \cdot \vec{v} = -\vec{v}$.}
\demostracionPropiedad{Inverso Aditivo mediante el Escalar $-1$}{Ejercicio}
\propiedad{Propiedad del Producto Nulo}{Si $\alpha \cdot \vec{v} = \vec{0}_V$, entonces $\alpha = 0$ o bien $\vec{v} = \vec{0}_V$.}
\demostracionPropiedad{Propiedad del Producto Nulo}{Ejercicio}
\propiedad{Ley de Cancelación Aditiva}{Si $\vec{u} + \vec{v} = \vec{u} + \vec{w}$, entonces $\vec{v} = \vec{w}$.}
\demostracionPropiedad{Ley de Cancelación Aditiva}{Ejercicio}
\end{propiedades}
\end{card}

\begin{card}

\begin{trampa}{Confusión entre $0 \in \mathbb{K}$ y $\vec{0}_V \in V$}
\error{Confundir el número escalar $0 \in \mathbb{K}$ con el vector nulo $\vec{0}_V \in V$, escribiendo relaciones matemáticamente inconsistentes como $0 \cdot \vec{v} = 0$ o $\vec{v} + 0 = \vec{v}$.}
\correct{El escalar $0$ es un número perteneciente al cuerpo $\mathbb{K}$ (como $0 \in \mathbb{R}$), mientras que $\vec{0}_V$ es un vector perteneciente al conjunto $V$ (como la matriz nula o el polinomio cero). La suma entre un vector $\vec{v}$ y un escalar $0$ no está definida. Siempre se debe escribir:
$$0 \cdot \vec{v} = \vec{0}_V \quad \text{y} \quad \vec{v} + \vec{0}_V = \vec{v}$$}
\end{trampa}
\end{card}

\begin{card} En la práctica, rara vez necesitamos construir un espacio vectorial completo verificando los 8 axiomas desde cero. Lo más común es trabajar con subconjuntos $H$ contenidos dentro de un espacio vectorial conocido $V$ (como $\mathbb{R}^n$, $\mathcal{M}_{mn}(\mathbb{R})$ o $\mathcal{P}_n[x](\mathbb{R})$) y verificar si heredan su estructura.

\begin{definicion}{Subespacio Vectorial ($H \le V$)}

Sea $(V, +, \cdot)$ un espacio vectorial sobre un cuerpo $\mathbb{K}$ y sea $H \subseteq V$ un subconjunto no vacío ($H \neq \emptyset$).

Diremos que $H$ es un \textbf{subespacio vectorial} de $V$ (y lo denotaremos por $H \le V$) si $H$, dotado de las mismas operaciones de suma $+$ y multiplicación por escalar $\cdot$ definidas en $V$, constituye por sí mismo un espacio vectorial sobre $\mathbb{K}$.
\end{definicion}

<p>\textbf{Subespacios Triviales:}</p>
Todo espacio vectorial $V$ contiene al menos dos subespacios vectoriales garantizados:
<ul class="list-disc pl-5 space-y-2">
  <li><strong>Subespacio Trivial Nulo:</strong> El conjunto $\{\vec{0}_V\} \le V$ formado únicamente por el elemento neutro.</li>
  <li><strong>Subespacio Total:</strong> El propio espacio $V \le V$.</li>
</ul>
Cualquier otro subespacio $H$ tal que $\{\vec{0}_V\} \subset H \subset V$ se denomina \textbf{subespacio propio}.
\end{card}

\begin{card}

Demostrar los 8 axiomas para un subconjunto $H \subseteq V$ sería un proceso tedioso y redundante, pues las propiedades algebraicas (como la conmutatividad o asociatividad) se heredan automáticamente de $V$. El siguiente teorema simplifica la comprobación a solo dos condiciones clave.

\begin{teorema}{Caracterización Abreviada de Subespacio Vectorial}

Sea $V$ un espacio vectorial sobre $\mathbb{K}$ y sea $H \subseteq V$. $H$ es un subespacio vectorial de $V$ ($H \le V$) si y solo si se cumplen las siguientes condiciones:

<ol class="list-decimal pl-5 space-y-2">
  <li><strong>No Vacuidad (Contiene a $\vec{0}_V$):</strong> $H \neq \emptyset$ (lo que equivale a verificar que $\vec{0}_V \in H$).</li>
  <li><strong>Clausura para la Suma Vectorial:</strong> Para todo $\vec{h}_1, \vec{h}_2 \in H$, se cumple que $(\vec{h}_1 + \vec{h}_2) \in H$.</li>
  <li><strong>Clausura para la Multiplicación Escalar:</strong> Para todo $\vec{h} \in H$ y todo $\alpha \in \mathbb{K},$ se cumple que $(\alpha \cdot \vec{h}) \in H$.</li>
</ol>


<p>\textbf{Formulación Combinada (Criterio en Un Solo Paso):}</p>
Las condiciones 2 y 3 se pueden unificar en un solo paso analítico:
$$\forall \vec{h}_1, \vec{h}_2 \in H \quad \text{y} \quad \forall \alpha \in \mathbb{K} \implies (\vec{h}_1 + \alpha \cdot \vec{h}_2) \in H$$

\demostracion{

<p>$(\Rightarrow)$ Si $H \le V$, $H$ es espacio vectorial y satisface por definición la no vaciedad y la clausura de ambas operaciones.</p>
<p>$(\Leftarrow)$ Supongamos que $H \subseteq V$ satisface $H \neq \emptyset$ y $\vec{h}_1 + \alpha \cdot \vec{h}_2 \in H$.</p>
<ul class="list-disc pl-5 space-y-2">
<li>Tomando $\alpha = -1$ y $\vec{h}_1 = \vec{h}_2 = \vec{h} \in H$, obtenemos $\vec{h} + (-1)\cdot \vec{h} = \vec{0}_V \in H$, luego el neutro pertenece a $H$.</li>
<li>Al pertenecer $\vec{0}_V$, para cualquier $\vec{h} \in H$, $(-1)\cdot \vec{h} = -\vec{h} \in H$, garantizando el inverso aditivo.</li>
<li>Los axiomas de asociatividad, conmutatividad y distributividad se heredan de manera inmediata por ser $H$ un subconjunto de $V$. Por lo tanto, $H \le V$.</li>
</ul>
}
\end{teorema}
\end{card}

\begin{card}

\begin{metodo}{Demostración de Subespacio mediante Criterio Abreviado}

\problema{Determinar si los siguientes conjuntos son subespacios vectoriales:
<ul class="list-disc pl-5 space-y-2">
  <li><strong>Caso A:</strong> $H_1 = \left\{ (x, y, z) \in \mathbb{R}^3 \mid x + 2y - z = 0 \right\} \subseteq \mathbb{R}^3$.</li>
  <li><strong>Caso B:</strong> $H_2 = \left\{ p(x) \in \mathcal{P}_3[x](\mathbb{R}) \mid p(0) = 1 \right\} \subseteq \mathcal{P}_3[x](\mathbb{R})$.</li>
</ul>}

\paso{1}{Verificar la no vaciedad probando si el neutro $\vec{0}_V$ pertenece al conjunto}
Evaluar las condiciones del conjunto con el elemento neutro aditivo.

\begin{ejemplo}
$\bullet$ Para $H_1$: El neutro en $\mathbb{R}^3$ es $\vec{0} = (0, 0, 0)$. Reemplazando: $0 + 2(0) - 0 = 0$. Por lo tanto, $\vec{0} \in H_1$ y $H_1 \neq \emptyset$.
$\bullet$ Para $H_2$: El neutro en $\mathcal{P}_3[x]$ es el polinomio nulo $p_0(x) = 0$. Evaluando en $x=0$: $p_0(0) = 0 \neq 1$.
Por lo tanto, el neutro aditivo no pertenece a $H_2$ ($\vec{0}_V \notin H_2$), concluyendo inmediatamente que $H_2$ \textbf{NO es un subespacio vectorial}.
\end{ejemplo}

\paso{2}{Demostrar la clausura de la combinación lineal en el caso favorable ($H_1$)}
Tomar dos elementos genéricos $\vec{h}_1 = (x_1, y_1, z_1)$ y $\vec{h}_2 = (x_2, y_2, z_2)$ de $H_1$ y un escalar $\alpha \in \mathbb{R}$, y probar que $(\vec{h}_1 + \alpha \vec{h}_2) \in H_1$.

\begin{ejemplo}
Dado que $\vec{h}_1, \vec{h}_2 \in H_1$, satisfacen las ecuaciones $x_1 + 2y_1 - z_1 = 0$ y $x_2 + 2y_2 - z_2 = 0$.
Formamos la combinación lineal:
$$\vec{h}_1 + \alpha \vec{h}_2 = (x_1 + \alpha x_2, \; y_1 + \alpha y_2, \; z_1 + \alpha z_2)$$
Evaluamos la condición de pertenencia a $H_1$:
$$(x_1 + \alpha x_2) + 2(y_1 + \alpha y_2) - (z_1 + \alpha z_2) = (x_1 + 2y_1 - z_1) + \alpha(x_2 + 2y_2 - z_2)$$
Como ambos paréntesis valen $0$:
$$0 + \alpha(0) = 0$$
Dado que satisface la ecuación definitoria, $(\vec{h}_1 + \alpha \vec{h}_2) \in H_1$.
Por lo tanto, $H_1 \le \mathbb{R}^3$ es un subespacio vectorial.
\end{ejemplo}

\end{metodo}

\end{card}

problems.pauta:
\textbf{DEMOSTRACIÓN PASO A PASO:}

1. \textbf{Descomposición del escalar cero:} En el cuerpo $\mathbb{K}$, el número $0$ cumple la identidad $0 = 0 + 0$. Por lo tanto:
$$0 \cdot \vec{v} = (0 + 0) \cdot \vec{v}$$

2. \textbf{Distributividad del vector respecto a la suma de escalares (Axioma 6):}
$$(0 + 0) \cdot \vec{v} = 0 \cdot \vec{v} + 0 \cdot \vec{v}$$

3. \textbf{Existencia del inverso aditivo (Axioma 4):} Como $(0 \cdot \vec{v}) \in V$, existe su inverso aditivo $-(0 \cdot \vec{v}) \in V$. Sumamos este inverso a ambos lados de la ecuación:
$$(0 \cdot \vec{v}) + (-(0 \cdot \vec{v})) = (0 \cdot \vec{v} + 0 \cdot \vec{v}) + (-(0 \cdot \vec{v}))$$

4. \textbf{Asociatividad de la suma (Axioma 2) en el lado derecho:}
$$\vec{0}_V = 0 \cdot \vec{v} + \left(0 \cdot \vec{v} + (-(0 \cdot \vec{v}))\right)$$

5. \textbf{Aplicación del inverso y neutro aditivo (Axiomas 4 y 3):}
$$\vec{0}_V = 0 \cdot \vec{v} + \vec{0}_V \implies \vec{0}_V = 0 \cdot \vec{v}$$

Concluyendo que $0 \cdot \vec{v} = \vec{0}_V$. $\blacksquare$

chapters.teoria:
\begin{card}


El concepto de combinación lineal es el bloque de construcción fundamental del álgebra lineal. Permite crear nuevos vectores mediante dos operaciones básicas: escalar vectores existentes y sumarlos.

\begin{definicion}{Combinación Lineal}

Sea $V$ un espacio vectorial sobre un cuerpo $\mathbb{K}$ y sea $S = \{\vec{v}_1, \vec{v}_2, \dots, \vec{v}_k\} \subseteq V$ un conjunto finito de vectores.

Diremos que un vector $\vec{v} \in V$ es una \textbf{combinación lineal} de los vectores del conjunto $S$ si existen escalares $\alpha_1, \alpha_2, \dots, \alpha_k \in \mathbb{K}$ tales que:

$$\vec{v} = \sum_{j=1}^k \alpha_j \vec{v}_j = \alpha_1 \vec{v}_1 + \alpha_2 \vec{v}_2 + \dots + \alpha_k \vec{v}_k$$
Los escalares $\alpha_1, \dots, \alpha_k$ reciben el nombre de \textbf{coeficientes} de la combinación lineal.
\end{definicion}
\end{card}
\begin{card}

Al tomar todas las combinaciones lineales posibles que se pueden formar con un grupo de vectores, construimos una estructura geométrica completa dentro del espacio vectorial.

\begin{definicion}{Conjunto Generado $\langle S \rangle$}

Sea $V$ un espacio vectorial sobre $\mathbb{K}$ y sea $S = \{\vec{v}_1, \vec{v}_2, \dots, \vec{v}_k\} \subseteq V$.
Se define el \textbf{conjunto generado} por $S$, denotado por $\langle S \rangle$ o por $\langle \{\vec{v}_1, \dots, \vec{v}_k\} \rangle$ como el conjunto formado por todas las combinaciones lineales posibles de los vectores de $S$:
$$\langle \{\vec{v}_1, \vec{v}_2, \dots, \vec{v}_k\} \rangle = \left\{ \sum_{j=1}^k \alpha_j \vec{v}_j \colon \alpha_j \in \mathbb{K}, \;\forall j = 1, \dots, k \right\}$$
\end{definicion}

\begin{teorema}{Teorema del Subespacio Generado}

Sea $V$ un espacio vectorial sobre $\mathbb{K}$ y sea $S = \{\vec{v}_1, \vec{v}_2, \dots, \vec{v}_k\} \subseteq V$.
<ol class="list-decimal pl-5 space-y-2">
<li>El conjunto generado $H = \langle S \rangle$ es siempre un \textbf{subespacio vectorial} de $V$ es decir $H \le V$.</li>
<li> A los vectores $\vec{v}_1, \dots, \vec{v}_k$ se les denomina \textbf{generadores} de $H$, y diremos que $S$ es un conjunto generador de $H$.</li>
<li>$\langle S \rangle$ es el \textbf{menor subespacio vectorial} de $V$ que contiene al conjunto $S$.</li>
</ol>


\demostracion{
\textbf{Demostración (Propiedad 1):}
- \textbf{No vacuidad:} El vector nulo $\vec{0}_V \in \langle S \rangle$, pues basta elegir todos los escalares $\alpha_j = 0$: $0\vec{v}_1 + \dots + 0\vec{v}_k = \vec{0}_V$.
- \textbf{Clausura de la combinación lineal:} Sean $\vec{u}, \vec{w} \in \langle S \rangle$ y $\lambda \in \mathbb{K}$. Entonces existen escalares $\alpha_j, \beta_j$ tales que $\vec{u} = \sum \alpha_j \vec{v}_j$ y $\vec{w} = \sum \beta_j \vec{v}_j$.
$$\vec{u} + \lambda \vec{w} = \sum_{j=1}^k \alpha_j \vec{v}_j + \lambda \sum_{j=1}^k \beta_j \vec{v}_j = \sum_{j=1}^k (\alpha_j + \lambda \beta_j) \vec{v}_j$$
Como los coeficientes $(\alpha_j + \lambda \beta_j) \in \mathbb{K}$, la expresión $(\vec{u} + \lambda \vec{w})$ es también una combinación lineal de $S$, por lo que $(\vec{u} + \lambda \vec{w}) \in \langle S \rangle$. Así, $\langle S \rangle \le V$.
}
\end{teorema}
\end{card}

\begin{card}
El estudio de si un vector $\vec{b}$ pertenece o no al conjunto generado por $S = \{\vec{v}_1, \dots, \vec{v}_k\}$ se reduce conceptualmente a la clasificación de un sistema de ecuaciones lineales:
<ul class="list-disc pl-5 space-y-2">
  <li><strong>Criterio de Pertenencia:</strong> $\vec{b} \in \langle S \rangle \iff$ El sistema de ecuaciones lineales $\displaystyle\sum_{j=1}^k \alpha_j \vec{v}_j = \vec{b}$ es <strong>compatible</strong> (sea determinado o indeterminado).</li>
  <li><strong>Criterio de No Pertenencia:</strong> $\vec{b} \notin \langle S \rangle \iff$ El sistema de ecuaciones lineales $\displaystyle\sum_{j=1}^k \alpha_j \vec{v}_j = \vec{b}$ es <strong>incompatible</strong> (no posee solución).</li>
</ul>



\begin{metodo}{Verificación de Pertenencia a un Conjunto Generado}

\problema{Determinar si el vector $\vec{b} = (1, 5, 2)$ pertenece al conjunto generado por $S = \{\vec{v}_1, \vec{v}_2\} \subseteq \mathbb{R}^3$, donde $\vec{v}_1 = (1, 1, 0)$ y $\vec{v}_2 = (0, 2, 1)$.}

\paso{1}{Plantear la ecuación de combinación lineal con coeficientes desconocidos}
Escribir la ecuación $\vec{b} = \alpha_1 \vec{v}_1 + \alpha_2 \vec{v}_2$.

\begin{ejemplo}
$$(1, 5, 2) = \alpha_1 (1, 1, 0) + \alpha_2 (0, 2, 1) = (\alpha_1, \; \alpha_1 + 2\alpha_2, \; \alpha_2)$$
\end{ejemplo}

\paso{2}{Formar el sistema de ecuaciones lineales asociado}
Igualar componente a componente para construir el sistema lineal en las incógnitas $\alpha_1, \alpha_2$.

\begin{ejemplo}
$$
\begin{cases}
\alpha_1 = 1 \\
\alpha_1 + 2\alpha_2 = 5 \\
\alpha_2 = 2
\end{cases}
$$
\end{ejemplo}

\paso{3}{Analizar la consistencia del sistema de ecuaciones}
Resolver el sistema. Si el sistema es compatible (admite solución), el vector pertenece al conjunto generado.

\begin{ejemplo}
De la 1.ª ecuación: $\alpha_1 = 1$. De la 3.ª ecuación: $\alpha_2 = 2$.
Sustituyendo en la 2.ª ecuación: $1 + 2(2) = 5$, lo cual es correcto ($5 = 5$).
Como el sistema es \textbf{compatible determinado} con solución $\alpha_1 = 1, \alpha_2 = 2$, concluimos que:
$$\vec{b} \in \langle S \rangle \quad \text{y} \quad \vec{b} = 1\vec{v}_1 + 2\vec{v}_2$$
\end{ejemplo}

\end{metodo}
\end{card}
\begin{card}
El concepto de independencia lineal permite saber si un conjunto de vectores contiene información "pura" o si alguno de sus elementos es superfluo o redundante por poder formarse a partir de los demás.

\begin{definicion}
\textbf{Independencia Lineal (L.I.) y Dependencia Lineal (L.D.)}

Sea $V$ un espacio vectorial sobre un cuerpo $\mathbb{K}$ y sea $S = \{\vec{v}_1, \vec{v}_2, \dots, \vec{v}_k\} \subseteq V$ un conjunto finito de vectores.

<ul class="list-disc pl-5 space-y-2">
  <li><strong>Conjunto Linealmente Independiente (L.I.):</strong> Diremos que $S$ es linealmente independiente si la única combinación lineal que produce el vector nulo $\vec{0}_V$ es aquella donde todos los escalares son estrictamente nulos:
  $$\sum_{j=1}^k \alpha_j \vec{v}_j = \vec{0}_V \implies \alpha_1 = \alpha_2 = \dots = \alpha_k = 0$$</li>
  <li><strong>Conjunto Linealmente Dependiente (L.D.):</strong> Diremos que $S$ es linealmente dependiente si existen escalares $\alpha_1, \alpha_2, \dots, \alpha_k \in \mathbb{K}$ <em>no todos nulos</em> (es decir, existe al menos un $\alpha_{j_0} \neq 0$) tales que:
  $$\sum_{j=1}^k \alpha_j \vec{v}_j = \vec{0}_V$$</li>
</ul>
\end{definicion}

<p>\textbf{Caracterización Alternativa de Dependencia Lineal:}</p>
Un conjunto de vectores $S = \{\vec{v}_1, \dots, \vec{v}_k\}$ es \textbf{L.D.} si y solo si al menos uno de sus vectores se puede escribir como combinación lineal de los restantes vectores del conjunto.
\end{card}

\begin{card}
<p>\textbf{Propiedades Fundamentales de Conjuntos L.I. y L.D.}</p>

Existen reglas geométricas y algebraicas directas para reconocer si un conjunto de vectores posee independencia lineal sin necesidad de resolver sistemas largos.

\begin{teorema}{Propiedades de Independencia Lineal}

Sea $V$ un espacio vectorial sobre $\mathbb{K}$.

<ul class="list-disc pl-5 space-y-2">
  <li><strong>Presencia del Vector Nulo:</strong> Todo conjunto de vectores $S \subseteq V$ que contenga al vector nulo $\vec{0}_V$ es siempre <strong>linealmente dependiente (L.D.)</strong>.</li>
  <li><strong>Conjunto de Un Solo Vector:</strong> El conjunto $\{\vec{v}\}$ es L.I. si y solo si $\vec{v} \neq \vec{0}_V$.</li>
  <li><strong>Conjunto de Dos Vectores:</strong> El conjunto $\{\vec{u}, \vec{v}\}$ es L.D. si y solo si uno de los vectores es un múltiplo escalar del otro ($\vec{u} = c\vec{v}$).</li>
  <li><strong>Subconjuntos y Superconjuntos:</strong> Todo subconjunto de un conjunto L.I. es L.I., y todo conjunto que contenga a un subconjunto L.D. es L.D.</li>
</ul>

\demostracion{
\textbf{Demostración (Presencia de} $\vec{0}_V$):
Sea $S = \{\vec{0}_V, \vec{v}_2, \dots, \vec{v}_k\}$. Consideremos la combinación lineal homogénea asignando $\alpha_1 = 1 \neq 0$ y todos los demás $\alpha_j = 0$:
$$1 \cdot \vec{0}_V + 0 \cdot \vec{v}_2 + \dots + 0 \cdot \vec{v}_k = \vec{0}_V + \vec{0}_V + \dots + \vec{0}_V = \vec{0}_V$$
Como hemos encontrado una combinación lineal nula con al menos un escalar no nulo ($\alpha_1 = 1$), el conjunto $S$ es L.D.
}\end{teorema}

\end{card}

\begin{card}

El estudio de independencia lineal se reduce a analizar la unicidad de solución de un sistema de ecuaciones lineales homogéneo.
<ul class="list-disc pl-5 space-y-2">
  <li><strong>Independencia Lineal (L.I.):</strong> El sistema homogéneo $A \vec{\alpha} = \vec{0}_V$ es <strong>Compatible Determinado</strong> (solución única trivial $\vec{\alpha} = \vec{0}$).</li>
  <li><strong>Dependencia Lineal (L.D.):</strong> El sistema homogéneo $A \vec{\alpha} = \vec{0}_V$ es <strong>Compatible Indeterminado</strong> (infinitas soluciones con escalares no todos nulos).</li>
</ul>

\begin{metodo}{Determinación de Independencia Lineal mediante Sistemas Homogéneos}

\problema{Determinar si el conjunto de polinomios $S = \{1 + x^2, \; 1 - x^2, \; x\} \subseteq \mathcal{P}_2[x](\mathbb{R})$ es linealmente independiente o linealmente dependiente.}

\paso{1}{Plantear la combinación lineal nula $\sum \alpha_j \vec{v}_j = \vec{0}_V$}
Plantear la ecuación homogénea con escalares desconocidos $\alpha_1, \alpha_2, \alpha_3$:
$$\alpha_1 (1 + x^2) + \alpha_2 (1 - x^2) + \alpha_3 (x) = 0 + 0x + 0x^2$$

\begin{ejemplo}
Agrupando términos según las potencias de $x$:
$$(\alpha_1 + \alpha_2) \cdot 1 + (\alpha_3) \cdot x + (\alpha_1 - \alpha_2) \cdot x^2 = 0 + 0x + 0x^2$$
\end{ejemplo}

\paso{2}{Formar y resolver el sistema de ecuaciones homogéneo resultante}
Igualar los coeficientes correspondientes a cada potencia de $x$ para obtener el sistema lineal homogéneo.

\begin{ejemplo}
$$
\begin{cases}
\alpha_1 + \alpha_2 = 0 \\
\alpha_3 = 0 \\
\alpha_1 - \alpha_2 = 0
\end{cases}
$$
Sumando la 1.ª y 3.ª ecuación: $2\alpha_1 = 0 \implies \alpha_1 = 0$.
Sustituyendo $\alpha_1$: $\alpha_2 = 0$.
De la 2.ª ecuación: $\alpha_3 = 0$.
\end{ejemplo}

\paso{3}{Clasificar el conjunto según la naturaleza de las soluciones}
Si la única solución es la trivial ($\alpha_1 = \alpha_2 = \alpha_3 = 0$), el conjunto es L.I. Si existen soluciones infinitas, es L.D.

\begin{ejemplo}
Como la única solución del sistema homogéneo es la solución trivial ($\alpha_1 = \alpha_2 = \alpha_3 = 0$), concluimos que el conjunto $S = \{1 + x^2, 1 - x^2, x\}$ es linealmente independiente (L.I.).
\end{ejemplo}

\end{metodo}


\end{card}

\begin{card}


Una base es el conjunto mínimo de generadores capaces de describir a todo un subespacio sin ninguna redundancia. La cantidad de elementos de una base mide la auténtica "libertad de movimiento" o dimensión del subespacio.

\begin{definicion}
\textbf{Base y Dimensión de un Subespacio}

Sea $V$ un espacio vectorial sobre un cuerpo $\mathbb{K}$ y sea $H \le V$ un subespacio vectorial de $V$.

Un conjunto de vectores $B = \{\vec{v}_1, \vec{v}_2, \dots, \vec{v}_k\} \subseteq H$ es una \textbf{base} de $H$ si satisface simultáneamente dos condiciones:
<ol class="list-decimal pl-5 space-y-2">
  <li><strong>Generación:</strong> $\langle B \rangle = H$, es decir, $B$ es un conjunto generador de $H$.</li>
  <li><strong>Independencia Lineal:</strong> $B$ es un conjunto linealmente independiente (L.I.).</li>
</ol>

\textbf{Dimensión} $\dim(H)$:
Si un subespacio $H$ posee una base finita de $k$ elementos, a la cantidad $k$ de vectores de la base la denominaremos \textbf{dimensión de} $H$ y la denotaremos por $\dim(H) = k$.
\end{definicion}

<p>\textbf{Invariancia de la Dimensión:}</p>
Un mismo subespacio $H$ admite infinitas bases distintas. Sin embargo, se demuestra que todas las bases de $H$ poseen \textbf{exactamente la misma cantidad de vectores}. Por lo tanto, la dimensión $\dim(H)$ es una propiedad única e intrínseca de $H$ que no depende de la base elegida.
\end{card}

\begin{card}
<p>\textbf{Bases Canónicas y Propiedades de Dimensión}</p>

Existen bases especialmente naturales para los espacios vectoriales más conocidos, denominadas bases canónicas.

\begin{teorema}{Bases Canónicas de Espacios Fundamentales}

<ul class="list-disc pl-5 space-y-2">
  <li><strong>Espacio $\mathbb{R}^n$:</strong> La base canónica es $B = \{\hat{e}_1, \hat{e}_2, \dots, \hat{e}_n\}$, donde $\hat{e}_i = (0, \dots, 1, \dots, 0)$ tiene un $1$ en la posición $i$ y ceros en las demás. Su dimensión es $\dim(\mathbb{R}^n) = n$.</li>
  <li><strong>Polinomios $\mathcal{P}_n[x](\mathbb{R})$:</strong> La base canónica es $B = \{1, x, x^2, \dots, x^n\}$. Posee $(n+1)$ elementos, por lo que su dimensión es $\dim(\mathcal{P}_n[x]) = n + 1$.</li>
  <li><strong>Matrices $\mathcal{M}_{mn}(\mathbb{R})$:</strong> La base canónica es el conjunto de matrices $B = \{E_{11}, E_{12}, \dots, E_{mn}\}$, donde $E_{ij}$ tiene un $1$ en la componente $ij$ y ceros en el resto. Su dimensión es $\dim(\mathcal{M}_{mn}) = m \cdot n$.</li>
</ul>
\end{teorema}

\begin{propiedades}{Propiedades de la Dimensión y Atajos de Verificación}

\propiedad{Acotación de Dimensión}{Si $H \le V$, entonces $\dim(H) \le \dim(V)$.}

\propiedad{Atajo por Independencia Lineal}{Si se sabe previamente que $\dim(H) = n$ y se tiene un conjunto $B \subseteq H$ con $n$ elementos que son L.I., entonces $B$ es automáticamente una base de $H$.}

\propiedad{Atajo por Generación}{Si se sabe previamente que $\dim(H) = n$ y se tiene un conjunto $B \subseteq H$ con $n$ elementos que generan a $H$, entonces $B$ es automáticamente una base de $H$.}

\propiedad{Límite de Independencia}{Si $\dim(H) = n$, cualquier subconjunto de $H$ con más de $n$ elementos es inevitablemente linealmente dependiente (L.D.).}

\propiedad{Dimensión del Espacio Trivial}{El subespacio formado únicamente por el vector nulo $\{\vec{0}_V\}$ tiene dimensión $0$, pues su base es el conjunto vacío $\emptyset$.}

\end{propiedades}
\end{card}

\begin{card}

\begin{metodo}{Obtención de una Base y Dimensión a partir de las Ecuaciones del Subespacio}

\problema{Encontrar una base y la dimensión del subespacio $H = \left\{ (x, y, z) \in \mathbb{R}^3 \mid 2x - y + z = 0 \right\} \subseteq \mathbb{R}^3$.}

\paso{1}{Despejar una variable dependiente en función de las variables libres}
De la ecuación definitoria $2x - y + z = 0$, despejar una variable en términos de las demás.

\begin{ejemplo}
Despejamos $z$:
$$z = -2x + y$$
Aquí $x$ e $y$ son las dos variables libres (parámetros independientes).
\end{ejemplo}

\paso{2}{Reemplazar en el vector genérico y descomponer en combinaciones lineales}
Sustituir la variable despejada en el vector genérico $\vec{x} = (x, y, z)$ y separar los términos correspondientes a cada variable libre.

\begin{ejemplo}
$$\vec{x} = \begin{pmatrix} x \\ y \\ z \end{pmatrix} = \begin{pmatrix} x \\ y \\ -2x + y \end{pmatrix} = \begin{pmatrix} x \\ 0 \\ -2x \end{pmatrix} + \begin{pmatrix} 0 \\ y \\ y \end{pmatrix} = x \begin{pmatrix} 1 \\ 0 \\ -2 \end{pmatrix} + y \begin{pmatrix} 0 \\ 1 \\ 1 \end{pmatrix}$$
\end{ejemplo}

\paso{3}{Extraer los vectores de la base y declarar la dimensión}
Los vectores que multiplican a los parámetros libres forman una base de $H$, y la cantidad de vectores extraídos determina $\dim(H)$.

\begin{ejemplo}
Los vectores obtenibles son $\vec{v}_1 = (1, 0, -2)$ y $\vec{v}_2 = (0, 1, 1)$.
Como son L.I. y generan todo el subespacio $H$, el conjunto:
$$B = \{(1, 0, -2), (0, 1, 1)\}$$
es una \textbf{base de} $H$, y la dimensión del subespacio es $\dim(H) = 2$.
\end{ejemplo}

\end{metodo}

\begin{trampa}{Dimensión del Espacio de Polinomios $\mathcal{P}_n[x]$}
\error{Asumir erróneamente que la dimensión del espacio de polinomios de grado menor o igual a $n$, $\mathcal{P}_n[x]$, es igual a $n$.}
\correct{La base canónica de $\mathcal{P}_n[x]$ es $\{1, x, x^2, \dots, x^n\}$, la cual incluye al término constante $1$ ($x^0$). Por este motivo, la cantidad total de elementos de la base es $(n + 1)$, de modo que $\dim(\mathcal{P}_n[x]) = n + 1$.}
\end{trampa}
\end{card}
\begin{card}\textbf{Espacio Generado y Dependencia/Independencia Lineal}
<div class="my-4 overflow-x-auto">
<table class="w-full text-sm text-left border-collapse border border-slate-300 dark:border-slate-700">
  <thead class="bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-slate-100 font-semibold">
    <tr>
      <th class="p-3 border border-slate-300 dark:border-slate-700">Concepto Vectorial</th>
      <th class="p-3 border border-slate-300 dark:border-slate-700">Sistema Asociado</th>
      <th class="p-3 border border-slate-300 dark:border-slate-700">Clasificación del Sistema</th>
      <th class="p-3 border border-slate-300 dark:border-slate-700">Condición Matricial / Rango</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td class="p-3 border border-slate-300 dark:border-slate-700"><strong>Pertenencia al Generado</strong><br>$\vec{b} \in \langle S \rangle$</td>
      <td class="p-3 border border-slate-300 dark:border-slate-700">No Homogéneo<br>$A \vec{\alpha} = \vec{b}$</td>
      <td class="p-3 border border-slate-300 dark:border-slate-700"><strong class="text-emerald-600 dark:text-emerald-400">Sistema Compatible</strong><br>(Determinado o Indeterminado)</td>
      <td class="p-3 border border-slate-300 dark:border-slate-700">$\operatorname{rango}(A) = \operatorname{rango}(A \mid \vec{b})$</td>
    </tr>
    <tr>
      <td class="p-3 border border-slate-300 dark:border-slate-700"><strong>No Pertenencia al Generado</strong><br>$\vec{b} \notin \langle S \rangle$</td>
      <td class="p-3 border border-slate-300 dark:border-slate-700">No Homogéneo<br>$A \vec{\alpha} = \vec{b}$</td>
