        // 1. Cuadrícula tenue
        ctx.beginPath();
        ctx.strokeStyle = '#f1f5f9';
        ctx.lineWidth = 1;
        for (let i = 0; i <= 9; i++) {
          ctx.moveTo(pt(i, 0).x, 0); ctx.lineTo(pt(i, 0).x, height);
          ctx.moveTo(0, pt(0, i).y); ctx.lineTo(width, pt(0, i).y);
        }
        ctx.stroke();

        // 2. Ejes Cartesiano X e Y
        drawArrow(0, 0, 9.6, 0, '#64748b', 1.5);
        drawArrow(0, 0, 0, 6.2, '#64748b', 1.5);

        // 3. Sombreado del Paralelogramo
        ctx.beginPath();
        ctx.fillStyle = 'rgba(168, 85, 247, 0.12)';
        ctx.moveTo(pt(0,0).x, pt(0,0).y);
        ctx.lineTo(pt(2,1).x, pt(2,1).y);
        ctx.lineTo(pt(3,4).x, pt(3,4).y);
        ctx.lineTo(pt(1,3).x, pt(1,3).y);
        ctx.closePath();
        ctx.fill();

        // 4. Dibujar según el Modo
        if (mode === 'paralelogramo') {
          // Líneas de referencia del paralelogramo
          ctx.beginPath();
          ctx.setLineDash([4, 4]);
          ctx.strokeStyle = '#94a3b8';
          ctx.lineWidth = 1.5;

          // Desde (2,1) hasta (3,4)
          ctx.moveTo(pt(2,1).x, pt(2,1).y); ctx.lineTo(pt(3,4).x, pt(3,4).y);
          // Desde (1,3) hasta (3,4)
          ctx.moveTo(pt(1,3).x, pt(1,3).y); ctx.lineTo(pt(3,4).x, pt(3,4).y);
          ctx.stroke();
          ctx.setLineDash([]);

          // Vector v en el origen
          drawArrow(0, 0, 1, 3, '#dc2626', 2.8);
          drawPoint(1, 3, '#b91c1c');

          lblV.style.top = '165px';
          lblV.style.left = '60px';
        } else {
          // Modo Cabeza a Cola: v se dibuja partiendo desde la punta de u (2,1)
          ctx.beginPath();
          ctx.setLineDash([4, 4]);
          ctx.strokeStyle = '#fca5a5';
          ctx.lineWidth = 1.2;
          ctx.moveTo(pt(0,0).x, pt(0,0).y); ctx.lineTo(pt(1,3).x, pt(1,3).y);
          ctx.stroke();
          ctx.setLineDash([]);

          drawArrow(2, 1, 3, 4, '#dc2626', 2.8);
          drawPoint(2, 1, '#1d4ed8');

          lblV.style.top = '185px';
          lblV.style.left = '165px';
        }

        // Vector u fijo (Azul)
        drawArrow(0, 0, 2, 1, '#2563eb', 2.8);
        drawPoint(0, 0, '#475569');
        drawPoint(2, 1, '#1d4ed8');

        // Vector Suma u + v (Verde Esmeralda)
        drawArrow(0, 0, 3, 4, '#059669', 3.2);
        drawPoint(3, 4, '#047857');
      }

      btn.onclick = () => {
        if (mode === 'paralelogramo') {
          mode = 'cabeza-cola';
          btn.innerHTML = '🔀 Alternar a Regla del Paralelogramo';
        } else {
          mode = 'paralelogramo';
          btn.innerHTML = '🔀 Alternar a Método Cabeza a Cola';
        }
        draw();
      };

      draw();
    }

    renderGraph();
  })();
</script>
