<script>
  (function() {
    function renderGraph() {
      const canvas = document.getElementById('canvasNormaR2');
      const rangeVx = document.getElementById('rangeVx');
      const rangeVy = document.getElementById('rangeVy');
      const txtVx = document.getElementById('txtVx');
      const txtVy = document.getElementById('txtVy');
      const lblCalculo = document.getElementById('lblCalculoNorma');

      if (!canvas || !rangeVx || !rangeVy || !lblCalculo) return setTimeout(renderGraph, 50);

      const ctx = canvas.getContext('2d');
      const width = canvas.width;
      const height = canvas.height;

      const sc = 45; // 1 unidad = 45px
      const cx = 55; // Origen X
      const cy = 300; // Origen Y

      const pt = (x, y) => ({ x: cx + x * sc, y: cy - y * sc });

      function drawArrow(x1, y1, x2, y2, col, widthLine = 2.5, dash = []) {
        const p1 = pt(x1, y1), p2 = pt(x2, y2);
        const len = Math.hypot(p2.x - p1.x, p2.y - p1.y);
        if (len < 2) return;

        const angle = Math.atan2(p2.y - p1.y, p2.x - p1.x);
        const headLen = 10;

        ctx.beginPath();
        ctx.setLineDash(dash);
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = col;
        ctx.lineWidth = widthLine;
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath();
        ctx.moveTo(p2.x, p2.y);
        ctx.lineTo(p2.x - headLen * Math.cos(angle - 0.35), p2.y - headLen * Math.sin(angle - 0.35));
        ctx.lineTo(p2.x - headLen * Math.cos(angle + 0.35), p2.y - headLen * Math.sin(angle + 0.35));
        ctx.closePath();
        ctx.fillStyle = col;
        ctx.fill();
      }

      function drawPoint(x, y, col = '#64748b') {
        const p = pt(x, y);
        ctx.beginPath();
        ctx.arc(p.x, p.y, 4.5, 0, 2 * Math.PI);
        ctx.fillStyle = col;
        ctx.fill();
      }

      function draw() {
        const vx = parseFloat(rangeVx.value);
        const vy = parseFloat(rangeVy.value);
        txtVx.textContent = vx;
        txtVy.textContent = vy;

        const normaVal = Math.hypot(vx, vy);
        const normaCuadrado = vx * vx + vy * vy;

        // Actualizar fórmula en KaTeX sin \langle ni \rangle
        if (window.katex) {
          katex.render(`\\|\\vec{v}\\| = \\sqrt{${vx}^2 + ${vy}^2} = \\sqrt{${normaCuadrado}} = ${normaVal.toFixed(2)}`, lblCalculo);
        } else {
          lblCalculo.textContent = `||v|| = sqrt(${vx}^2 + ${vy}^2) = ${normaVal.toFixed(2)}`;
        }

        ctx.clearRect(0, 0, width, height);

        // 1. Cuadrícula tenue
        ctx.beginPath();
        ctx.strokeStyle = '#f1f5f9';
        ctx.lineWidth = 1;
        for (let i = 0; i <= 9; i++) {
          ctx.moveTo(pt(i, 0).x, 0); ctx.lineTo(pt(i, 0).x, height);
          ctx.moveTo(0, pt(0, i).y); ctx.lineTo(width, pt(0, i).y);
        }
        ctx.stroke();

        // 2. Ejes Cartesiano X e Y
        drawArrow(0, 0, 9.6, 0, '#64748b', 1.5);
        drawArrow(0, 0, 0, 6.2, '#64748b', 1.5);

        // 3. Sombreado del Triángulo Rectángulo Pitagórico
        ctx.beginPath();
        ctx.fillStyle = 'rgba(59, 130, 246, 0.08)';
        ctx.moveTo(pt(0, 0).x, pt(0, 0).y);
        ctx.lineTo(pt(vx, 0).x, pt(vx, 0).y);
        ctx.lineTo(pt(vx, vy).x, pt(vx, vy).y);
        ctx.closePath();
        ctx.fill();

        // 4. Marca de Ángulo Recto (90º) en (vx, 0)
        const pSquare = pt(vx, 0);
        const sqSize = 12;
        ctx.beginPath();
        ctx.strokeStyle = '#64748b';
