        ctx.lineTo(pSquare.x - sqSize, pSquare.y - sqSize);
        ctx.lineTo(pSquare.x, pSquare.y - sqSize);
        ctx.stroke();

        // 5. Catetos del Triángulo Rectángulo (Punteados)
        // Cateto horizontal vx
        ctx.beginPath();
        ctx.strokeStyle = '#d97706';
        ctx.lineWidth = 2.5;
        ctx.moveTo(pt(0, 0).x, pt(0, 0).y);
        ctx.lineTo(pt(vx, 0).x, pt(vx, 0).y);
        ctx.stroke();

        // Cateto vertical vy
        ctx.beginPath();
        ctx.strokeStyle = '#059669';
        ctx.lineWidth = 2.5;
        ctx.moveTo(pt(vx, 0).x, pt(vx, 0).y);
        ctx.lineTo(pt(vx, vy).x, pt(vx, vy).y);
        ctx.stroke();

        // 6. Vector Principal v (Hipotenusa) [Azul Cobalt]
        drawArrow(0, 0, vx, vy, '#2563eb', 3.2);
