        ▶ Explorar Plano (s, t)
      </button>
      <button id="btnResetParams_plano" style="background: #e0f2fe; color: #0369a1; border: 1px solid #bae6fd; padding: 4px 10px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600;">
        Restablecer \((s,t)\)
      </button>
    </div>
    <!-- Botones de Vistas Predefinidas y Pantalla Completa -->
    <div style="display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; align-items: center;">
      <button id="btnVX_plano" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje X</button>
      <button id="btnVY_plano" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje Y</button>
      <button id="btnVZ_plano" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer;">Vista Eje Z (Cenital)</button>
      <button id="btnReset_plano" style="background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 5px 10px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600;">Restablecer Vista</button>
      <button id="btnFS_plano" style="background: #0284c7; color: #ffffff; border: 1px solid #0369a1; padding: 5px 12px; border-radius: 6px; font-size: 12px; cursor: pointer; font-weight: 600; display: flex; align-items: center; gap: 5px;">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"/></svg>
        Pantalla Completa
      </button>
    </div>
    <div style="font-size: 11px; color: #64748b; line-height: 1.4;">
      💡 <b>Arrastrar ratón:</b> Rotar vista 3D &nbsp;|&nbsp; <b>Rueda:</b> Zoom al centro &nbsp;|&nbsp; <b>Shift + Rueda:</b> Zoom al puntero &nbsp;|&nbsp; <b>Flechas:</b> Desplazar
    </div>
  </div>
</div>
<script>
(function() {
  const container = document.getElementById('containerPlano3D');
  const wrapper = document.getElementById('wrapperPlano3D');
  const canvas = document.getElementById('canvasPlano3D');
  const ctx = canvas.getContext('2d');
  const sliderS = document.getElementById('sliderParamS');
  const sliderT = document.getElementById('sliderParamT');
  const valS = document.getElementById('valParamS');
  const valT = document.getElementById('valParamT');
  const infoOverlay = document.getElementById('infoPlano3D');
  const btnAnim = document.getElementById('btnAnimPlano');
  // Etiquetas KaTeX flotantes
  const lblP  = document.getElementById('labelP_plano');
  const lblU  = document.getElementById('labelU_plano');
  const lblV  = document.getElementById('labelV_plano');
  const lblN  = document.getElementById('labelN_plano');
  const lblX  = document.getElementById('labelX_plano');
  const lblPi = document.getElementById('labelPi_plano');
  // Geometría del Plano
  const P0 = { x: 1.0, y: 1.0, z: 1.0 };
  const U  = { x: 2.0, y: 0.0, z: 1.0 };
  const V  = { x: 0.0, y: 2.0, z: 1.0 };
  // Normal n = u x v = (-2, -2, 4) -> escalado para visualización
  const N  = { x: -1.5, y: -1.5, z: 3.0 };
  let paramS = parseFloat(sliderS.value);
  let paramT = parseFloat(sliderT.value);
  let isAnimating = false;
  let animId = null;
  let animAngle = 0;
  // Cámara (Estándar 1 Oficial)
  let yaw = -0.65;
  let pitch = 0.45;
  let zoom = 1.0;
  let panX = 0;
  let panY = 0;
  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };
  // Proyección 3D a 2D
  function project3D(x, y, z) {
    const cosY = Math.cos(yaw), sinY = Math.sin(yaw);
    const x1 = x * cosY - y * sinY;
    const y1 = x * sinY + y * cosY;
    const z1 = z;
    const cosP = Math.cos(pitch), sinP = Math.sin(pitch);
    const x2 = x1;
    const y2 = y1 * cosP - z1 * sinP;
    const z2 = y1 * sinP + z1 * cosP;
    const currentScale = 35 * zoom;
    const cx = canvas.width / 2 + panX;
    const cy = canvas.height / 2 + panY;
    return {
      px: cx + x2 * currentScale,
      py: cy - z2 * currentScale,
      zDepth: y2
    };
  }
  function drawLine3D(pA, pB, color, width = 1.5, dash = []) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    ctx.save();
    ctx.beginPath();
    ctx.setLineDash(dash);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();
    ctx.restore();
  }
  function drawVector3D(pA, pB, color, width = 2) {
    const a = project3D(pA.x, pA.y, pA.z);
    const b = project3D(pB.x, pB.y, pB.z);
    const dx = b.px - a.px;
    const dy = b.py - a.py;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) return;
    ctx.save();
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.moveTo(a.px, a.py);
    ctx.lineTo(b.px, b.py);
    ctx.stroke();
    const angle = Math.atan2(dy, dx);
    const headLen = 9;
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.moveTo(b.px, b.py);
    ctx.lineTo(b.px - headLen * Math.cos(angle - Math.PI / 6), b.py - headLen * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(b.px - headLen * Math.cos(angle + Math.PI / 6), b.py - headLen * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  function drawPoint3D(pt, color, radius = 4) {
    const p = project3D(pt.x, pt.y, pt.z);
    ctx.save();
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.arc(p.px, p.py, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.restore();
  }
  // Dibujar Superficie Plana Malla Sombreada 3D
  function drawPlaneSurface() {
    const rMin = -1.2, rMax = 1.2;
    const corners = [
      { x: P0.x + rMin * U.x + rMin * V.x, y: P0.y + rMin * U.y + rMin * V.y, z: P0.z + rMin * U.z + rMin * V.z },
      { x: P0.x + rMax * U.x + rMin * V.x, y: P0.y + rMax * U.y + rMin * V.y, z: P0.z + rMax * U.z + rMin * V.z },
      { x: P0.x + rMax * U.x + rMax * V.x, y: P0.y + rMax * U.y + rMax * V.y, z: P0.z + rMax * U.z + rMax * V.z },
      { x: P0.x + rMin * U.x + rMax * V.x, y: P0.y + rMin * U.y + rMax * V.y, z: P0.z + rMin * U.z + rMax * V.z }
    ];
    const pts2D = corners.map(pt => project3D(pt.x, pt.y, pt.z));
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(pts2D[0].px, pts2D[0].py);
    ctx.lineTo(pts2D[1].px, pts2D[1].py);
    ctx.lineTo(pts2D[2].px, pts2D[2].py);
    ctx.lineTo(pts2D[3].px, pts2D[3].py);
    ctx.closePath();
    ctx.fillStyle = 'rgba(56, 189, 248, 0.15)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(2, 132, 199, 0.4)';
    ctx.lineWidth = 1.2;
    ctx.stroke();
    // Dibujar rejilla interna sobre el plano
    const step = 0.5;
    ctx.strokeStyle = 'rgba(2, 132, 199, 0.2)';
    ctx.lineWidth = 0.8;
    for (let s = -1.0; s <= 1.0; s += step) {
      const pA = { x: P0.x + s * U.x - 1.2 * V.x, y: P0.y + s * U.y - 1.2 * V.y, z: P0.z + s * U.z - 1.2 * V.z };
      const pB = { x: P0.x + s * U.x + 1.2 * V.x, y: P0.y + s * U.y + 1.2 * V.y, z: P0.z + s * U.z + 1.2 * V.z };
      const p2DA = project3D(pA.x, pA.y, pA.z);
      const p2DB = project3D(pB.x, pB.y, pB.z);
      ctx.beginPath(); ctx.moveTo(p2DA.px, p2DA.py); ctx.lineTo(p2DB.px, p2DB.py); ctx.stroke();
    }
    for (let t = -1.0; t <= 1.0; t += step) {
      const pA = { x: P0.x - 1.2 * U.x + t * V.x, y: P0.y - 1.2 * U.y + t * V.y, z: P0.z - 1.2 * U.z + t * V.z };
      const pB = { x: P0.x + 1.2 * U.x + t * V.x, y: P0.y + 1.2 * U.y + t * V.y, z: P0.z + 1.2 * U.z + t * V.z };
      const p2DA = project3D(pA.x, pA.y, pA.z);
      const p2DB = project3D(pB.x, pB.y, pB.z);
      ctx.beginPath(); ctx.moveTo(p2DA.px, p2DA.py); ctx.lineTo(p2DB.px, p2DB.py); ctx.stroke();
    }
    ctx.restore();
  }
  function drawGrid3D() {
    ctx.beginPath();
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = -1; i <= 5; i++) {
      const pA1 = project3D(i, -1, 0), pA2 = project3D(i, 5, 0);
      ctx.moveTo(pA1.px, pA1.py); ctx.lineTo(pA2.px, pA2.py);
      const pB1 = project3D(-1, i, 0), pB2 = project3D(5, i, 0);
      ctx.moveTo(pB1.px, pB1.py); ctx.lineTo(pB2.px, pB2.py);
    }
    ctx.stroke();
  }
  function drawAxes3D() {
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, { x: 5.2, y: 0, z: 0 }, '#000000', 2.0); // Eje X
    drawVector3D(O, { x: 0, y: 5.2, z: 0 }, '#000000', 2.0); // Eje Y
    drawVector3D(O, { x: 0, y: 0, z: 5.2 }, '#000000', 2.0); // Eje Z
    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#000000';
    const px = project3D(5.5, 0, 0);
    const py = project3D(0, 5.5, 0);
    const pz = project3D(0, 0, 5.5);
    ctx.fillText('x', px.px, px.py);
    ctx.fillText('y', py.px, py.py);
    ctx.fillText('z', pz.px, pz.py);
    // Graduación y Marcas de Numeración en el Eje Z (1, 2, 3, 4, 5)
    for (let zVal = 1; zVal <= 5; zVal++) {
      const ptZ = project3D(0, 0, zVal);
      const ptTick = project3D(0.12, 0, zVal);
      ctx.save();
      ctx.beginPath();
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 1.2;
      ctx.moveTo(ptZ.px, ptZ.py);
      ctx.lineTo(ptTick.px, ptTick.py);
      ctx.stroke();
      ctx.font = '10px sans-serif';
      ctx.fillStyle = '#334155';
      ctx.fillText(zVal.toString(), ptTick.px + 4, ptTick.py + 3);
      ctx.restore();
    }
  }
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    drawGrid3D();
    drawAxes3D();
    // 1. Dibujar la Superficie del Plano \Pi
    drawPlaneSurface();
    // 2. Punto Posición P y Vector p (Origen -> P)
    const O = { x: 0, y: 0, z: 0 };
    drawVector3D(O, P0, '#0284c7', 2.0);
    drawPoint3D(P0, '#0284c7', 5);
    // 3. Vectores Directores u y v aplicados en P
    const U_end = { x: P0.x + U.x, y: P0.y + U.y, z: P0.z + U.z };
    const V_end = { x: P0.x + V.x, y: P0.y + V.y, z: P0.z + V.z };
    drawVector3D(P0, U_end, '#059669', 2.5);
    drawVector3D(P0, V_end, '#d97706', 2.5);
    // 4. Vector Normal n = u x v (Perpendicular al plano \Pi)
    const N_end = { x: P0.x + N.x, y: P0.y + N.y, z: P0.z + N.z };
    drawVector3D(P0, N_end, '#e11d48', 3.0);
    // 5. Punto Generado x(s, t) = p + s*u + t*v
    const X_curr = {
      x: P0.x + paramS * U.x + paramT * V.x,
      y: P0.y + paramS * U.y + paramT * V.y,
      z: P0.z + paramS * U.z + paramT * V.z
    };
    // Vector Desplazamiento (x - p) contenido en el plano
    drawLine3D(P0, X_curr, '#8b5cf6', 2.2);
    drawPoint3D(X_curr, '#8b5cf6', 6);
    // Indicador de Ángulo Recto 90º entre el Vector Normal n y el Desplazamiento (x - p)
    const lenDisp = Math.hypot(X_curr.x - P0.x, X_curr.y - P0.y, X_curr.z - P0.z);
    const lenN = Math.hypot(N.x, N.y, N.z);
    if (lenDisp > 0.3) {
      const uDisp = { x: (X_curr.x - P0.x) / lenDisp, y: (X_curr.y - P0.y) / lenDisp, z: (X_curr.z - P0.z) / lenDisp };
      const uN = { x: N.x / lenN, y: N.y / lenN, z: N.z / lenN };
      const sSize = 0.35;
      const c1 = { x: P0.x + sSize * uDisp.x, y: P0.y + sSize * uDisp.y, z: P0.z + sSize * uDisp.z };
      const c2 = { x: P0.x + sSize * uDisp.x + sSize * uN.x, y: P0.y + sSize * uDisp.y + sSize * uN.y, z: P0.z + sSize * uDisp.z + sSize * uN.z };
      const c3 = { x: P0.x + sSize * uN.x, y: P0.y + sSize * uN.y, z: P0.z + sSize * uN.z };
      const pC1 = project3D(c1.x, c1.y, c1.z);
      const pC2 = project3D(c2.x, c2.y, c2.z);
      const pC3 = project3D(c3.x, c3.y, c3.z);
      ctx.save();
      ctx.beginPath();
      ctx.strokeStyle = '#e11d48';
      ctx.lineWidth = 1.8;
      ctx.moveTo(pC1.px, pC1.py);
      ctx.lineTo(pC2.px, pC2.py);
      ctx.lineTo(pC3.px, pC3.py);
      ctx.stroke();
      ctx.restore();
    }
    // Actualizar Posición de Etiquetas KaTeX Flotantes
    const posP0 = project3D(P0.x, P0.y, P0.z);
    const posU  = project3D(P0.x + U.x * 0.5, P0.y + U.y * 0.5, P0.z + U.z * 0.5);
    const posV  = project3D(P0.x + V.x * 0.5, P0.y + V.y * 0.5, P0.z + V.z * 0.5);
    const posN  = project3D(N_end.x, N_end.y, N_end.z);
    const posX  = project3D(X_curr.x, X_curr.y, X_curr.z);
    const posPi = project3D(P0.x + 1.2 * U.x + 1.2 * V.x, P0.y + 1.2 * U.y + 1.2 * V.y, P0.z + 1.2 * U.z + 1.2 * V.z);
    if (lblP)  { lblP.style.left  = posP0.px + 'px'; lblP.style.top  = (posP0.py - 12) + 'px'; }
    if (lblU)  { lblU.style.left  = posU.px + 'px';  lblU.style.top  = (posU.py - 12) + 'px'; }
    if (lblV)  { lblV.style.left  = posV.px + 'px';  lblV.style.top  = (posV.py - 12) + 'px'; }
    if (lblN)  { lblN.style.left  = posN.px + 'px';  lblN.style.top  = (posN.py - 14) + 'px'; }
    if (lblX)  { lblX.style.left  = posX.px + 'px';  lblX.style.top  = (posX.py - 14) + 'px'; }
    if (lblPi) { lblPi.style.left = posPi.px + 'px'; lblPi.style.top = (posPi.py - 10) + 'px'; }
    // Actualizar Panel de Información Overlay KaTeX
    if (infoOverlay) {
      infoOverlay.innerHTML = `
        <div style="color: #0284c7; font-weight: 700; margin-bottom: 2px;">Ecuaciones del Plano \\(\\Pi\\)</div>
        <div style="color: #334155; font-size: 12px;">Punto de anclaje: \\(\\vec{p} = (1.00, 1.00, 1.00)\\)</div>
        <div style="color: #059669; font-size: 12px; margin-top: 3px;"><b>1. Paramétrica:</b> \\(\\vec{x} = \\vec{p} + s\\vec{u} + t\\vec{v}\\)</div>
        <div style="color: #334155; font-size: 11px; margin-left: 10px;">Para \\(s = ${paramS.toFixed(2)}, t = ${paramT.toFixed(2)}\\): \\(\\vec{x} = (${X_curr.x.toFixed(2)}, ${X_curr.y.toFixed(2)}, ${X_curr.z.toFixed(2)})\\)</div>
        <div style="color: #e11d48; font-size: 12px; margin-top: 4px;"><b>2. Cartesiana (Normal):</b> \\(\\vec{n} \\cdot (\\vec{x} - \\vec{p}) = 0\\)</div>
        <div style="color: #334155; font-size: 11px; margin-left: 10px;">Ecuación: \\(x + y - 2z = 0\\)</div>
      `;
      if (window.renderMathInElement) {
        window.renderMathInElement(infoOverlay, { delimiters: [{ left: '\\(', right: '\\)', display: false }] });
      }
    }
  }
  // Sliders s y t
  sliderS.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    paramS = parseFloat(e.target.value);
    valS.textContent = paramS.toFixed(2);
    draw();
  });
  sliderT.addEventListener('input', (e) => {
    if (isAnimating) stopAnimation();
    paramT = parseFloat(e.target.value);
    valT.textContent = paramT.toFixed(2);
    draw();
  });
  // Animación suave de exploración del plano
  function animatePlaneExploration() {
    if (isAnimating) {
      stopAnimation();
      return;
    }
    isAnimating = true;
    btnAnim.innerHTML = '⏸ Pausar';
    function stepAnim() {
      if (!isAnimating) return;
      animAngle += 0.025;
      paramS = 0.8 * Math.cos(animAngle);
      paramT = 0.8 * Math.sin(animAngle);
      sliderS.value = paramS;
      sliderT.value = paramT;
      valS.textContent = paramS.toFixed(2);
      valT.textContent = paramT.toFixed(2);
      draw();
      animId = requestAnimationFrame(stepAnim);
    }
    stepAnim();
  }
  function stopAnimation() {
    isAnimating = false;
    if (animId) cancelAnimationFrame(animId);
    btnAnim.innerHTML = '▶ Explorar Plano (s, t)';
  }
  btnAnim.onclick = animatePlaneExploration;
  document.getElementById('btnResetParams_plano').onclick = () => {
    if (isAnimating) stopAnimation();
    paramS = 0.5; paramT = 0.5;
    sliderS.value = 0.5; sliderT.value = 0.5;
    valS.textContent = '0.50'; valT.textContent = '0.50';
    draw();
  };
  // Navegación con Ratón
  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    prevMousePos = { x: e.clientX, y: e.clientY };
  });
  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - prevMousePos.x;
    const deltaY = e.clientY - prevMousePos.y;
    yaw += deltaX * 0.008;
    pitch = Math.max(-1.55, Math.min(1.55, pitch + deltaY * 0.008));
    prevMousePos = { x: e.clientX, y: e.clientY };
    draw();
  });
  window.addEventListener('mouseup', () => {
    isDragging = false;
    canvas.style.cursor = 'grab';
  });
  // Zoom con la Rueda
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const oldZoom = zoom;
    let newZoom = oldZoom;
    if (e.deltaY < 0) newZoom = Math.min(3.5, oldZoom * 1.08);
    else newZoom = Math.max(0.3, oldZoom / 1.08);
    if (e.shiftKey) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const scaleRatio = newZoom / oldZoom;
      const originX = (canvas.width / 2) + panX;
      const originY = (canvas.height / 2) + panY;
      panX = mouseX - (mouseX - originX) * scaleRatio - (canvas.width / 2);
      panY = mouseY - (mouseY - originY) * scaleRatio - (canvas.height / 2);
    }
    zoom = newZoom;
    draw();
  }, { passive: false });
  // Traslación con Flechas Teclado
  window.addEventListener('keydown', (e) => {
    if (document.activeElement === sliderS || document.activeElement === sliderT) return;
    const step = 15;
    if (e.key === 'ArrowLeft') { panX -= step; draw(); }
    else if (e.key === 'ArrowRight') { panX += step; draw(); }
    else if (e.key === 'ArrowUp') { panY -= step; draw(); }
    else if (e.key === 'ArrowDown') { panY -= step; draw(); }
  });
  // Botones de Vistas Ortogonales
  document.getElementById('btnVX_plano').onclick = () => { yaw = -Math.PI / 2; pitch = 0; draw(); };
  document.getElementById('btnVY_plano').onclick = () => { yaw = 0; pitch = 0; draw(); };
  document.getElementById('btnVZ_plano').onclick = () => { yaw = 0; pitch = Math.PI / 2 - 0.001; draw(); };
  document.getElementById('btnReset_plano').onclick = () => {
    yaw = -0.65; pitch = 0.45; zoom = 1.0; panX = 0; panY = 0; draw();
  };
  // Pantalla Completa Adaptativa 100%
  document.getElementById('btnFS_plano').onclick = () => {
    if (!document.fullscreenElement) {
      if (container.requestFullscreen) container.requestFullscreen();
      else if (container.webkitRequestFullscreen) container.webkitRequestFullscreen();
    } else {
      if (document.exitFullscreen) document.exitFullscreen();
    }
  };
  function updateCanvasSize() {
    if (document.fullscreenElement) {
      container.style.width = '100vw';
      container.style.height = '100vh';
      container.style.borderRadius = '0';
      container.style.padding = '16px';
      container.style.display = 'flex';
      container.style.flexDirection = 'column';
